template<class Type>
Field<Type> readList(const fileName& fName)
{
 IFstream is(fName)
 if (!is.good)
 {
 FatalErrorInFunction
 << "Cannot open boundary data file " << fName << nl
 << exit(FatalError)
 }
 List<Type> lst(is)
 return Field<Type>(lst)
}


template<class Type>
Type interpolateZ(const scalarField& zp, const Field<Type>& f, const scalar z)
{
 const label n = zp.size
 if (n == 1 || z <= zp[0]) return f[0]
 if (z >= zp[n-1]) return f[n-1]
 label lo = 0, hi = n - 1
 while (hi - lo > 1)
 {
 const label mid = (lo + hi)/2
 if (zp[mid] <= z) lo = mid; else hi = mid
 }
 const scalar d = zp[hi] - zp[lo]
 if (d < vSmall) return f[lo]
 const scalar w = (z - zp[lo])/d
 return (1 - w)*f[lo] + w*f[hi]
}


scalarList uniqueSorted(const scalarList& vals, const scalar tol)
{
 scalarList v(vals)
 sort(v)
 DynamicList<scalar> u(v.size)
 forAll(v, i)
 {
 if (u.empty || v[i] - u.last > tol)
 {
 u.append(v[i])
 }
 }
 scalarList res
 res.transfer(u)
 return res
}


label nearestIndex(const scalarList& g, const scalar v)
{
 const label n = g.size
 if (n == 1 || v <= g[0]) return 0
 if (v >= g[n-1]) return n - 1
 label lo = 0, hi = n - 1
 while (hi - lo > 1)
 {
 const label mid = (lo + hi)/2
 if (g[mid] <= v) lo = mid; else hi = mid
 }
 return (v - g[lo] <= g[hi] - v) ? lo : hi
}


// Unit-variance exponential-correlation filter, rho = exp(-|dx|/L)
// periodic : one-sided kernel a^m with wrap-around (uniform spacing delta)
// otherwise: exact AR(1) recursion along the actual coordinates x
void expFilter
(
 scalarList& r
 const scalarList& x
 const scalarList& L
 const bool periodic
 const scalar delta
 const scalar filterFactor
)
{
 const label n = r.size
 if (n < 2) return
 scalarList out(n, 0.0)
 if (periodic)
 {
 for (label j = 0; j < n; j++)
 {
 const scalar Lj = L[j]
 if (delta <= 0 || Lj <= small*delta)
 {
 out[j] = r[j]
 continue
 }
 const scalar a = exp(-delta/Lj)
 const scalar Ks = filterFactor*Lj/delta
 const label K =
 (Ks >= scalar(n - 1)) ? n - 1 : label(std::ceil(Ks))
 scalar s = 0, s2 = 0, b = 1
 for (label m = 0; m <= K; m++)
 {
 s += b*r[(j + m) % n]
 s2 += b*b
 b *= a
 }
 out[j] = s/sqrt(s2)
 }
 }
 else
 {
 out[0] = r[0]
 for (label j = 1; j < n; j++)
 {
 const scalar Lm = 0.5*(L[j] + L[j-1])
 const scalar a =
 (Lm > small) ? scalar(exp(-(x[j] - x[j-1])/Lm)) : scalar(0)
 out[j] = a*out[j-1] + sqrt(max(1 - a*a, scalar(0)))*r[j]
 }
 }

 r.transfer(out)
}

