Foam::scalar Foam::turbulentDFMVeerInletFvPatchVectorField::gaussian
{
 if (haveSpare_)
 {
 haveSpare_ = false
 return spare_
 }
 scalar u1 = rnd_.scalar01
 while (u1 < vSmall)
 {
 u1 = rnd_.scalar01
 }
 const scalar u2 = rnd_.scalar01
 const scalar rr = sqrt(-2.0*log(u1))
 const scalar th = constant::mathematical::twoPi*u2
 spare_ = rr*sin(th)
 haveSpare_ = true
 return rr*cos(th)
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::readProfiles
{
 const Time& rt = db.time
 const fileName dir =
 rt.rootPath/rt.globalCaseName/rt.constant
 /"boundaryData"/patch.name
 const pointField pts(dfmVeer::readList<vector>(dir/"points"))
 const scalarField U (dfmVeer::readList<scalar>(dir/"U"))
 const symmTensorField R (dfmVeer::readList<symmTensor>(dir/"R"))
 const tensorField L (dfmVeer::readList<tensor>(dir/"L"))
 const scalarField psi(dfmVeer::readList<scalar>(dir/"psi"))
 const label n = pts.size
 if
 (
 n == 0 || U.size != n || R.size != n
 || L.size != n || psi.size != n
)
 {
 FatalErrorInFunction
 << "Inconsistent sizes in " << dir << ": points " << n
 << " U " << U.size << " R " << R.size
 << " L " << L.size << " psi " << psi.size
 << exit(FatalError)
 }

 const scalarField zRaw(pts.component(vector::Z))
 labelList order
 sortedOrder(zRaw, order)
 zProf_.setSize(n)
 UProf_.setSize(n)
 psiProf_.setSize(n)
 RProf_.setSize(n)
 LProf_.setSize(n)
 const scalar deg2rad = constant::mathematical::pi/180.0
 forAll(order, i)
 {
 const label o = order[i]
 zProf_[i] = zRaw[o]
 UProf_[i] = U[o]
 psiProf_[i] = psi[o]*deg2rad
 RProf_[i] = R[o]
 LProf_[i] = L[o]
 }

 Umax_ = max(mag(UProf_))
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::buildGrid
{
 // Gather all face centres (identical grid on all processors)
 List<pointField> allCf(Pstream::nProcs)
 allCf[Pstream::myProcNo] = patch.Cf
 Pstream::gatherList(allCf)
 Pstream::scatterList(allCf)
 label nAll = 0
 forAll(allCf, proci)
 {
 nAll += allCf[proci].size
 }
 if (nAll == 0)
 {
 FatalErrorInFunction
 << "Patch " << patch.name << " has no faces"
 << exit(FatalError)
 }

 scalarList ys(nAll), zs(nAll)
 scalar yMin = great, yMax = -great, zMin = great, zMax = -great
 label cnt = 0
 forAll(allCf, proci)
 {
 forAll(allCf[proci], i)
 {
 ys[cnt] = allCf[proci][i].y
 zs[cnt] = allCf[proci][i].z
 yMin = min(yMin, ys[cnt]); yMax = max(yMax, ys[cnt])
 zMin = min(zMin, zs[cnt]); zMax = max(zMax, zs[cnt])
 cnt++
 }
 }

 const scalar span = max(max(yMax - yMin, zMax - zMin), small)
 const scalar tol = 1e-6*span
 scalarList yU(dfmVeer::uniqueSorted(ys, tol))
 scalarList zU(dfmVeer::uniqueSorted(zs, tol))
 if (scalar(yU.size)*scalar(zU.size) <= 2.0*scalar(nAll))
 {
 // Structured (blockMesh-like) inlet: use the actual grid lines
 yGrid_.transfer(yU)
 zGrid_.transfer(zU)
 }
 else
 {
 // Unstructured inlet: uniform virtual grid, nearest-node mapping
 const scalar area = (yMax - yMin)*(zMax - zMin)
 const scalar h =
 (area > sqr(tol)) ? sqrt(area/nAll) : span/scalar(nAll)
 const label nyv = max(label(1), label((yMax - yMin)/h + 0.5) + 1)
 const label nzv = max(label(1), label((zMax - zMin)/h + 0.5) + 1)
 yGrid_.setSize(nyv)
 zGrid_.setSize(nzv)
 forAll(yGrid_, j)
 {
 yGrid_[j] = yMin + j*(yMax - yMin)/max(nyv - 1, label(1))
 }
 forAll(zGrid_, k)
 {
 zGrid_[k] = zMin + k*(zMax - zMin)/max(nzv - 1, label(1))
 }

 WarningInFunction
 << "Patch " << patch.name << " is not a structured "
 << "y-z grid; using a uniform virtual grid "
 << nyv << " x " << nzv << endl
 }

 ny_ = yGrid_.size
 nz_ = zGrid_.size
 dy_ = (ny_ > 1) ? (yGrid_[ny_-1] - yGrid_[0])/(ny_ - 1) : 0
 dz_ = (nz_ > 1) ? (zGrid_[nz_-1] - zGrid_[0])/(nz_ - 1) : 0
 const vectorField& Cf = patch.Cf
 faceNode_.setSize(Cf.size)
 forAll(Cf, f)
 {
 const label j = dfmVeer::nearestIndex(yGrid_, Cf[f].y)
 const label k = dfmVeer::nearestIndex(zGrid_, Cf[f].z)
 faceNode_[f] = j + ny_*k
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::computeRowData
{
 Tk_.setSize(nz_)
 Lyk_.setSize(nz_)
 Lzk_.setSize(nz_)
 UcK_.setSize(nz_)
 sinK_.setSize(nz_)
 cosK_.setSize(nz_)
 const scalar Ufloor = max(1e-3*Umax_, small)
 forAll(zGrid_, k)
 {
 const scalar z = zGrid_[k]
 const scalar Uz = dfmVeer::interpolateZ(zProf_, UProf_, z)
 const scalar psi = dfmVeer::interpolateZ(zProf_, psiProf_, z)
 const tensor L = dfmVeer::interpolateZ(zProf_, LProf_, z)
 scalar Uc = (constMeanU_ && Uref_ > 0) ? Uref_ : Uz
 Uc = max(Uc, Ufloor)
 const scalar c = cos(psi)
 const scalar s = sin(psi)
 if (c < 1e-3)
 {
 FatalErrorInFunction
 << "Mean wind direction psi = " << psi*180/constant::mathematical::pi
 << " deg at z = " << z << " does not enter through the "
 << "inlet (cos psi <= 0)" << exit(FatalError)
 }

 UcK_[k] = Uc
 sinK_[k] = s
 cosK_[k] = c
 for (direction i = 0; i < vector::nComponents; i++)
 {
 // L_ij: local component i along local direction j (row-major)
 const scalar Lx = max(L.component(3*i + 0), scalar(0))
 const scalar Ly = max(L.component(3*i + 1), scalar(0))
 const scalar Lz = max(L.component(3*i + 2), scalar(0))
 Tk_[k].component(i) = Lx/Uc
 if (useDelay_)
 {
 Lyk_[k].component(i) = Ly/c
 }
 else
 {
 scalar inv = 0
 if (mag(s) > small)
 {
 inv += (Lx > small) ? mag(s)/Lx : great
 }
 inv += (Ly > small) ? c/Ly : great
 Lyk_[k].component(i) = (inv > small) ? 1.0/inv : 0.0
 }

 Lzk_[k].component(i) = Lz
 }
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::computeDelays
{
 nodeDelay_.setSize(ny_*nz_)
 nodeDelay_ = 0
 maxDelay_ = 0
 if (!useDelay_) return
 const scalar yc = 0.5*(yGrid_[0] + yGrid_[ny_-1])
 for (label k = 0; k < nz_; k++)
 {
 for (label j = 0; j < ny_; j++)
 {
 nodeDelay_[j + ny_*k] = (yGrid_[j] - yc)*sinK_[k]/UcK_[k]
 }
 }

 const scalar dmin = min(nodeDelay_)
 nodeDelay_ -= dmin
 maxDelay_ = max(nodeDelay_)
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::computeFaceData
{
 const vectorField& Cf = patch.Cf
 Umean_.setSize(Cf.size)
 M_.setSize(Cf.size)
 faceDelay_.setSize(Cf.size)
 forAll(Cf, f)
 {
 const scalar z = Cf[f].z
 const scalar Uz = dfmVeer::interpolateZ(zProf_, UProf_, z)
 const scalar psi = dfmVeer::interpolateZ(zProf_, psiProf_, z)
 const symmTensor R = dfmVeer::interpolateZ(zProf_, RProf_, z)
 const scalar c = cos(psi)
 const scalar s = sin(psi)
 Umean_[f] = Uz*vector(c, s, 0)
 // Lund (Cholesky) in the local frame
 const scalar a11 = sqrt(max(R.xx, scalar(0)))
 const scalar a21 = (a11 > small) ? R.xy/a11 : 0
 const scalar a31 = (a11 > small) ? R.xz/a11 : 0
 const scalar a22 = sqrt(max(R.yy - sqr(a21), scalar(0)))
 const scalar a32 = (a22 > small) ? (R.yz - a21*a31)/a22 : 0
 const scalar a33 =
 sqrt(max(R.zz - sqr(a31) - sqr(a32), scalar(0)))
 const tensor A(a11, 0, 0, a21, a22, 0, a31, a32, a33)
 const tensor Q(c, -s, 0, s, c, 0, 0, 0, 1)
 M_[f] = (Q & A)
 faceDelay_[f] = nodeDelay_[faceNode_[f]]
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::generatePhi
(
 vectorField& phi
)
{
 const label nNodes = ny_*nz_
 phi.setSize(nNodes)
 forAll(phi, n)
 {
 const scalar g0 = gaussian
 const scalar g1 = gaussian
 const scalar g2 = gaussian
 phi[n] = vector(g0, g1, g2)
 }

 scalarList row(ny_), Lrow(ny_), col(nz_), Lcol(nz_)
 for (direction i = 0; i < vector::nComponents; i++)
 {
 // y-direction, row by row
 for (label k = 0; k < nz_; k++)
 {
 for (label j = 0; j < ny_; j++)
 {
 row[j] = phi[j + ny_*k].component(i)
 Lrow[j] = Lyk_[k].component(i)
 }
 dfmVeer::expFilter
 (
 row, yGrid_, Lrow, periodicInY_, dy_, filterFactor_
)
 for (label j = 0; j < ny_; j++)
 {
 phi[j + ny_*k].component(i) = row[j]
 }
 }

 // z-direction, column by column
 for (label j = 0; j < ny_; j++)
 {
 for (label k = 0; k < nz_; k++)
 {
 col[k] = phi[j + ny_*k].component(i)
 Lcol[k] = Lzk_[k].component(i)
 }
 dfmVeer::expFilter
 (
 col, zGrid_, Lcol, periodicInZ_, dz_, filterFactor_
)
 for (label k = 0; k < nz_; k++)
 {
 phi[j + ny_*k].component(i) = col[k]
 }
 }
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::advance(const scalar dt)
{
 vectorField phi
 generatePhi(phi)
 forAll(Psi_, n)
 {
 const label k = n/ny_
 for (direction i = 0; i < vector::nComponents; i++)
 {
 const scalar T = Tk_[k].component(i)
 const scalar a = (T > small) ? scalar(exp(-dt/T)) : scalar(0)
 Psi_[n].component(i) =
 a*Psi_[n].component(i)
 + sqrt(max(1 - a*a, scalar(0)))*phi[n].component(i)
 }
 }
}


Foam::scalar Foam::turbulentDFMVeerInletFvPatchVectorField::ageTime
(
 const label age
) const
{
 const label cap = buf_.size
 return bufTime_[(bufHead_ - age + cap) % cap]
}


const Foam::vectorField&
Foam::turbulentDFMVeerInletFvPatchVectorField::plane(const label age) const
{
 const label cap = buf_.size
 return buf_[(bufHead_ - age + cap) % cap]
}


Foam::label Foam::turbulentDFMVeerInletFvPatchVectorField::nearestAge
(
 const scalar t
) const
{
 if (bufSize_ <= 1 || t >= ageTime(0)) return 0
 label lo = 0, hi = bufSize_ - 1
 if (t <= ageTime(hi)) return hi
 while (hi - lo > 1)
 {
 const label mid = (lo + hi)/2
 if (ageTime(mid) > t) lo = mid; else hi = mid
 }
 return (ageTime(lo) - t <= t - ageTime(hi)) ? lo : hi
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::pushPlane(const scalar t)
{
 if (buf_.empty)
 {
 buf_.setSize(4)
 bufTime_.setSize(4)
 bufHead_ = -1
 bufSize_ = 0
 }

 label cap = buf_.size
 // Drop the oldest plane if the second oldest already covers t - maxDelay
 while (bufSize_ >= 2)
 {
 const label second = (bufHead_ - (bufSize_ - 2) + cap) % cap
 if (bufTime_[second] <= t - maxDelay_)
 {
 bufSize_--
 }
 else
 {
 break
 }
 }

 if (bufSize_ == cap)
 {
 if (cap >= bufCapMax_)
 {
 if (!growWarned_)
 {
 WarningInFunction
 << "History buffer limit reached (maxBufferMB); the "
 << "largest trace delays will be clipped" << endl
 growWarned_ = true
 }
 bufSize_--; // overwrite the oldest plane
 }
 else
 {
 const label newCap = min(max(2*cap, cap + 1), bufCapMax_)
 List<vectorField> nb(newCap)
 scalarList nt(newCap, 0.0)
 for (label m = 0; m < bufSize_; m++)
 {
 const label src = (bufHead_ - (bufSize_ - 1) + m + cap) % cap
 nb[m].transfer(buf_[src])
 nt[m] = bufTime_[src]
 }
 buf_.transfer(nb)
 bufTime_.transfer(nt)
 bufHead_ = bufSize_ - 1
 cap = newCap
 }
 }

 bufHead_ = (bufHead_ + 1) % cap
 buf_[bufHead_] = Psi_
 bufTime_[bufHead_] = t
 bufSize_++
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialise
{
 readProfiles
 buildGrid
 useDelay_ = traceDelay_
 computeRowData
 computeDelays
 const label nNodes = ny_*nz_
 const scalar bytesPerPlane = 3.0*sizeof(scalar)*max(nNodes, label(1))
 bufCapMax_ = max(label(4), label(maxBufferMB_*1e6/bytesPerPlane))
 const scalar dt0 = max(db.time.deltaTValue, small)
 label nPre = 0
 if (useDelay_ && maxDelay_ > 0)
 {
 const scalar nNeed = maxDelay_/dt0 + 3
 if (nNeed > scalar(bufCapMax_))
 {
 WarningInFunction
 << "Trace delay needs ~" << nNeed << " history planes, more "
 << "than maxBufferMB allows; falling back to the "
 << "projected-lateral-scale model (traceDelay off)" << endl
 useDelay_ = false
 computeRowData
 computeDelays
 }
 else
 {
 nPre = label(std::ceil(maxDelay_/dt0)) + 1
 }
 }

 computeFaceData
 haveSpare_ = false
 generatePhi(Psi_); // stationary initial state

 buf_.clear
 bufTime_.clear
 bufHead_ = -1
 bufSize_ = 0
 const scalar t0 = db.time.value
 if (useDelay_)
 {
 buf_.setSize(nPre + 3)
 bufTime_.setSize(nPre + 3, 0.0)
 // Spin up a stationary history ending at t0
 pushPlane(t0 - nPre*dt0)
 for (label m = 1; m <= nPre; m++)
 {
 advance(dt0)
 pushPlane(t0 - (nPre - m)*dt0)
 }
 }

 lastTime_ = t0
 curTimeIndex_ = db.time.timeIndex
 initialised_ = true
 Info<< "turbulentDFMVeerInlet on patch " << patch.name
 << ": grid " << ny_ << " x " << nz_
 << ", traceDelay " << Switch(useDelay_)
 << ", max delay " << maxDelay_ << " s"
 << ", history planes " << nPre << endl
}


