Foam::turbulentDFMVeerInletFvPatchVectorField::
turbulentDFMVeerInletFvPatchVectorField
(
 const fvPatch& p
 const DimensionedField<vector, volMesh>& iF
 const dictionary& dict
)
:
 fixedValueFvPatchVectorField(p, iF, dict)
 filterType_(dict.lookupOrDefault<word>("filterType", "exponential"))
 filterFactor_(dict.lookupOrDefault<scalar>("filterFactor", 4))
 periodicInY_(dict.lookupOrDefault<bool>("periodicInY", false))
 periodicInZ_(dict.lookupOrDefault<bool>("periodicInZ", false))
 constMeanU_(dict.lookupOrDefault<bool>("constMeanU", false))
 Uref_(dict.lookupOrDefault<scalar>("Uref", 0))
 traceDelay_(dict.lookupOrDefault<bool>("traceDelay", true))
 seed_(dict.lookupOrDefault<label>("seed", 1234))
 maxBufferMB_(dict.lookupOrDefault<scalar>("maxBufferMB", 1024))
 initialised_(false)
 useDelay_(false)
 curTimeIndex_(-1)
 lastTime_(0)
 rnd_(seed_)
 haveSpare_(false)
 spare_(0)
 growWarned_(false)
 Umax_(0)
 ny_(0)
 nz_(0)
 dy_(0)
 dz_(0)
 maxDelay_(0)
 bufHead_(-1)
 bufSize_(0)
 bufCapMax_(4)
{
 if (filterType_ != "exponential")
 {
 WarningInFunction
 << "filterType " << filterType_ << " not implemented; "
 << "using exponential" << endl
 }
 if (filterFactor_ <= 0)
 {
 filterFactor_ = 4
 }
 if (constMeanU_ && Uref_ <= 0)
 {
 WarningInFunction
 << "constMeanU true but Uref <= 0; using local U(z)" << endl
 }
}


