void Foam::turbulentDFMVeerInletFvPatchVectorField::updateCoeffs
{
 if (this->updated)
 {
 return
 }

 const label timeIndex = this->db.time.timeIndex
 if (curTimeIndex_ != timeIndex)
 {
 if (!initialised_)
 {
 initialise
 }
 else if (ny_*nz_ > 0)
 {
 const scalar dt = this->db.time.deltaTValue
 vectorField aT(nz_)
 forAll(aT, k)
 {
 for (direction i = 0; i < 3; ++i)
 {
 aT[k][i] = Foam::exp(-dt/max(Tv_[k][i], vSmall))
 }
 }

 vectorField psiNew
 spatialField(psiNew)
 forAll(Phi_, idx)
 {
 const vector& a = aT[idx/ny_]
 for (direction i = 0; i < 3; ++i)
 {
 Phi_[idx][i] =
 a[i]*Phi_[idx][i]
 + Foam::sqrt(max(1 - a[i]*a[i], scalar(0)))
 *psiNew[idx][i]
 }
 }
 }

 curTimeIndex_ = timeIndex
 if (ny_*nz_ > 0)
 {
 const label ny = ny_
 vectorField Up(this->patch.size)
 forAll(Up, f)
 {
 const scalar wy = fWy_[f]
 const scalar wz = fWz_[f]
 const vector phi =
 (1 - wy)*(1 - wz)*Phi_[fJ0_[f] + ny*fK0_[f]]
 + wy*(1 - wz)*Phi_[fJ1_[f] + ny*fK0_[f]]
 + (1 - wy)*wz*Phi_[fJ0_[f] + ny*fK1_[f]]
 + wy*wz*Phi_[fJ1_[f] + ny*fK1_[f]]
 Up[f] = fUmean_[f] + (fM_[f] & phi)
 }
 this->operator==(Up)
 }
 }

 fixedValueFvPatchVectorField::updateCoeffs
}


