Foam::label Foam::turbulentDFMVeerInletFvPatchVectorField::makeSeed
(
 const label seed
 const label timeIndex
)
{
 if (seed >= 0)
 {
 // Reproducible; offset by processor and time index so that a
 // restart does not replay the same random sequence
 return seed + 7919*Pstream::myProcNo + 104729*timeIndex
 }

 const long t = long(std::time(nullptr) % 1000003L)
 return label((Pstream::myProcNo + 1)*t + 1)
}


Foam::scalar Foam::turbulentDFMVeerInletFvPatchVectorField::bessi0
(
 const scalar x
)
{
 scalar ax, ans, y
 if ((ax = mag(x)) < 3.75)
 {
 y = x/3.75
 y = y*y
 ans = 1.0 + y*(3.5156229 + y*(3.0899424 + y*(1.2067492
 + y*(0.2659732 + y*(0.360768e-1 + y*0.45813e-2)))))
 }
 else
 {
 y = 3.75/ax
 ans = (exp(ax)/sqrt(ax))*(0.39894228 + y*(0.-1
 + y*(0.225319e-2 + y*(-0.157565e-2 + y*(0.916281e-2
 + y*(-0.-1 + y*(0.-1 + y*(-0.-1
 + y*0.392377e-2))))))))
 }

 return ans
}


Foam::scalar Foam::turbulentDFMVeerInletFvPatchVectorField::bessk0
(
 const scalar x
)
{
 scalar y, ans
 if (x <= 2.0)
 {
 y = x*x/4.0
 ans = (-log(x/2.0)*bessi0(x)) + (-0.57721566 + y*(0.42278420
 + y*(0.23069756 + y*(0.-1 + y*(0.262698e-2
 + y*(0.10750e-3 + y*0.74e-5))))))
 }
 else
 {
 y = 2.0/x
 ans = (exp(-x)/sqrt(x))*(1.25331414 + y*(-0.-1
 + y*(0.-1 + y*(-0.-1 + y*(0.587872e-2
 + y*(-0.251540e-2 + y*0.53208e-3))))))
 }

 return ans
}


