Foam::turbulentDFMVeerInletFvPatchVectorField::interpolateHeight
(
 const Field<Type>& sampleVals
 const word& fieldName
) const
{
 const fileName pointsFile(boundaryDataDir/"points")
 if (!isFile(pointsFile))
 {
 FatalErrorInFunction
 << "Cannot find " << pointsFile << exit(FatalError)
 }

 IFstream pis(pointsFile)
 const pointField samplePoints(pis)
 if (samplePoints.empty || samplePoints.size != sampleVals.size)
 {
 FatalErrorInFunction
 << "Field " << fieldName << " has " << sampleVals.size
 << " values but " << pointsFile << " has "
 << samplePoints.size << " points" << exit(FatalError)
 }

 const scalarField hs(samplePoints & vertical_)
 labelList order
 sortedOrder(hs, order)
 const scalar tol = 1e-6*(max(hs) - min(hs)) + 1e-9
 // Height profile: average samples sharing (nearly) the same height
 DynamicList<scalar> hProf
 DynamicList<Type> vProf
 label i = 0
 while (i < order.size)
 {
 const scalar h0 = hs[order[i]]
 scalar hSum = 0
 Type vSum = pTraits<Type>::zero
 label n = 0
 while (i < order.size && hs[order[i]] - h0 <= tol)
 {
 hSum += hs[order[i]]
 vSum += sampleVals[order[i]]
 ++n
 ++i
 }

 hProf.append(hSum/n)
 vProf.append(vSum/scalar(n))
 }

 const label np = hProf.size
 const scalarField hf(patch.Cf & vertical_)
 tmp<Field<Type>> tvals(new Field<Type>(hf.size, pTraits<Type>::zero))
 Field<Type>& vals = tvals.ref
 label nClamped = 0
 forAll(hf, facei)
 {
 const scalar h = hf[facei]
 if (np == 1 || h <= hProf[0])
 {
 if (np > 1 && h < hProf[0] - tol)
 {
 ++nClamped
 }
 vals[facei] = vProf[0]
 }
 else if (h >= hProf[np - 1])
 {
 if (h > hProf[np - 1] + tol)
 {
 ++nClamped
 }
 vals[facei] = vProf[np - 1]
 }
 else
 {
 label k = 0
 while (k < np - 2 && hProf[k + 1] <= h)
 {
 ++k
 }

 const scalar w = (h - hProf[k])/(hProf[k + 1] - hProf[k])
 vals[facei] = (1.0 - w)*vProf[k] + w*vProf[k + 1]
 }
 }

 reduce(nClamped, sumOp<label>)
 Info<< "turbulentDFMVeerInlet " << patch.name << ": " << fieldName
 << " interpolated in height from " << np << " levels" << endl
 if (nClamped)
 {
 WarningInFunction
 << nClamped << " faces of patch " << patch.name
 << " lie outside the height range of the " << fieldName
 << " profile; end values used" << endl
 }

 return tvals
}


template<class Type>
Foam::tmp<Foam::Field<Type>>
Foam::turbulentDFMVeerInletFvPatchVectorField::readProfile
(
 const word& fieldName
 const dictionary& dict
) const
{
 if (dict.found(fieldName))
 {
 return tmp<Field<Type>>
 (
 new Field<Type>(fieldName, dict, patch.size)
)
 }

 const fileName valsFile(boundaryDataDir/fieldName)
 if (!isFile(valsFile))
 {
 FatalIOErrorInFunction(dict)
 << "Neither keyword " << fieldName << " nor file " << valsFile
 << " found" << exit(FatalIOError)
 }

 IFstream is(valsFile)
 const Field<Type> sampleVals(is)
 return interpolateHeight(sampleVals, fieldName)
}


Foam::tmp<Foam::scalarField>
Foam::turbulentDFMVeerInletFvPatchVectorField::readPsi
(
 const dictionary& dict
) const
{
 if (dict.found("psi"))
 {
 return tmp<scalarField>
 (
 new scalarField("psi", dict, patch.size)
)
 }

 const fileName psiFile(boundaryDataDir/"psi")
 if (!isFile(psiFile))
 {
 Info<< "turbulentDFMVeerInlet " << patch.name
 << ": no psi data found, psi = 0 (no veer)" << endl
 return tmp<scalarField>(new scalarField(patch.size, 0.0))
 }

 IFstream is(psiFile)
 const scalarField psiSamples(is)
 // Interpolate the direction (cos, sin) rather than the angle itself
 // which is safe across the +-180 deg discontinuity
 vectorField dirSamples(psiSamples.size, vector::zero)
 forAll(psiSamples, i)
 {
 const scalar a = degToRad(psiSamples[i])
 dirSamples[i] = vector(cos(a), sin(a), 0)
 }

 const vectorField dirFaces(interpolateHeight(dirSamples, word("psi")))
 tmp<scalarField> tpsi(new scalarField(patch.size, 0.0))
 scalarField& psi = tpsi.ref
 forAll(psi, facei)
 {
 const vector& d = dirFaces[facei]
 if (sqr(d.x) + sqr(d.y) < small)
 {
 FatalErrorInFunction
 << "Ill-defined interpolated wind direction at face "
 << facei << " (opposite directions at neighbouring levels)"
 << exit(FatalError)
 }

 psi[facei] = radToDeg(atan2(d.y, d.x))
 }

 return tpsi
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::calcGeometry
{
 const vectorField nf(patch.nf)
 // Inward unit normal (same convention as TInF)
 patchNormal_ = -gAverage(nf)
 if (mag(patchNormal_) < small)
 {
 FatalErrorInFunction
 << "Cannot determine the normal of patch " << patch.name
 << exit(FatalError)
 }

 forAll(patchNormal_, d)
 {
 if (mag(patchNormal_[d]) <= small)
 {
 patchNormal_[d] = 0
 }
 }
 patchNormal_ /= mag(patchNormal_)
 if (gMax(magSqr(nf + patchNormal_)) > 1e-6)
 {
 WarningInFunction
 << "Patch " << patch.name << " is not planar" << endl
 }

 // Vertical axis orthogonal to the patch normal
 const vector v(vertical_ - (vertical_ & patchNormal_)*patchNormal_)
 if (mag(v) < small)
 {
 FatalErrorInFunction
 << "verticalAxis is parallel to the normal of patch "
 << patch.name << exit(FatalError)
 }

 vertical_ = v/mag(v)
 // In-plane horizontal axis (= +y for normal +x and vertical +z)
 tangent_ = vertical_ ^ patchNormal_
 tangent_ /= mag(tangent_)
 patchSize_.setSize(Pstream::nProcs)
 patchSize_ = 0
 patchSize_[Pstream::myProcNo] = patch.size
 Pstream::gatherList(patchSize_)
 Pstream::scatterList(patchSize_)
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseFrames
{
 label nWeak = 0
 forAll(psi_, facei)
 {
 const scalar a = degToRad(psi_[facei])
 const vector ex(cos(a)*patchNormal_ + sin(a)*tangent_)
 const vector ey(vertical_ ^ ex)
 eMean_[facei] = ex
 // tensor(a, b, c) takes rows; transpose -> columns e_x' e_y' e_z'
 Q_[facei] = tensor(ex, ey, vertical_).T
 if ((ex & patchNormal_) < 0.1)
 {
 ++nWeak
 }
 }

 reduce(nWeak, sumOp<label>)
 if (nWeak)
 {
 WarningInFunction
 << nWeak << " faces have |psi| > ~84 deg: the mean flow is "
 << "(almost) tangential to or out of patch " << patch.name
 << endl
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseParameters
{
 label nBadU = 0
 label nBadR = 0
 label nBadL = 0
 label nFallback = 0
 forAll(U_, facei)
 {
 if (U_[facei] <= 0)
 {
 ++nBadU
 }

 // Lund / Cholesky factor of the local Reynolds stress
 const symmTensor& R = R_[facei]
 const scalar trR = max(R.xx + R.yy + R.zz, vSmall)
 const scalar eps = 1e-10*trR
 tensor B(tensor::zero)
 bool bad = false
 const scalar d0 = R.xx
 if (d0 > eps)
 {
 B.xx = sqrt(d0)
 B.yx = R.xy/B.xx
 B.zx = R.xz/B.xx
 }
 else if (d0 < -eps)
 {
 bad = true
 }

 const scalar d1 = R.yy - sqr(B.yx)
 if (d1 > eps)
 {
 B.yy = sqrt(d1)
 B.zy = (R.yz - B.yx*B.zx)/B.yy
 }
 else if (d1 < -eps)
 {
 bad = true
 }

 const scalar d2 = R.zz - sqr(B.zx) - sqr(B.zy)
 if (d2 > eps)
 {
 B.zz = sqrt(d2)
 }
 else if (d2 < -eps)
 {
 bad = true
 }

 if (bad)
 {
 ++nBadR
 }

 Lund_[facei] = B
 // Target scales: column 0 = along wind (time), column 1 = in-plane
 // horizontal t (ellipsoidal projection), column 2 = vertical
 const tensor& L = L_[facei]
 const vector& ex = eMean_[facei]
 const vector ey(vertical_ ^ ex)
 const scalar a = ex & tangent_; // sin(psi)
 const scalar b = ey & tangent_; // cos(psi)

 tensor Le(L)
 bool badL = false
 for (direction i = 0; i < 3; i++)
 {
 const scalar Lx = L.component(3*i)
 const scalar Ly = L.component(3*i + 1)
 const scalar Lz = L.component(3*i + 2)
 if (Lx <= 0 || Ly <= 0 || Lz <= 0)
 {
 badL = true
 }

 if (mag(a) > small && Lx > 0 && Ly > 0)
 {
 Le.component(3*i + 1) =
 1.0/sqrt(sqr(a/Lx) + sqr(b/Ly))
 }
 }

 if (badL)
 {
 ++nBadL
 }

 // Mixing matrix E_ik = B_ik^2/R_ii and L0 = inv(E) & Leff
 const scalar Rd[3] = {R.xx, R.yy, R.zz}
 tensor E(tensor::zero)
 for (direction i = 0; i < 3; i++)
 {
 if (Rd[i] > eps)
 {
 for (direction k = 0; k < 3; k++)
 {
 E.component(3*i + k) = sqr(B.component(3*i + k))/Rd[i]
 }
 }
 else
 {
 E.component(3*i + i) = 1
 }
 }

 tensor L0(Le)
 if (det(E) > 1e-12)
 {
 L0 = inv(E) & Le
 bool negative = false
 for (direction c = 0; c < tensor::nComponents; c++)
 {
 if (L0.component(c) < 0)
 {
 negative = true
 }
 }

 if (negative)
 {
 L0 = Le
 ++nFallback
 }
 }
 else
 {
 ++nFallback
 }

 Leff_[facei] = Le
 L0_[facei] = L0
 }

 reduce(nBadU, sumOp<label>)
 reduce(nBadR, sumOp<label>)
 reduce(nBadL, sumOp<label>)
 reduce(nFallback, sumOp<label>)
 if (nBadU)
 {
 WarningInFunction
 << nBadU << " faces with U <= 0" << endl
 }
 if (nBadR)
 {
 WarningInFunction
 << nBadR << " faces with non positive semi-definite R; "
 << "negative pivots set to zero" << endl
 }
 if (nBadL)
 {
 WarningInFunction
 << nBadL << " faces with non-positive L components" << endl
 }

 Info<< "turbulentDFMVeerInlet " << patch.name << ": "
 << nFallback << " faces use L0 = Leff (no mixing correction)"
 << endl
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseVirtualGrid
{
 const vectorField& Cf = patch.Cf
 const scalarField sY(Cf & tangent_)
 const scalarField sZ(Cf & vertical_)
 originY_ = gMin(sY)
 originZ_ = gMin(sZ)
 const scalar spanY = gMax(sY) - originY_
 const scalar spanZ = gMax(sZ) - originZ_
 delta_ = sqrt(gMin(patch.magSf))/gridFactor_
 My_ = label(ceil(spanY/delta_)) + 1
 Mz_ = label(ceil(spanZ/delta_)) + 1
 const scalarField sYAll(gatherProc(sY))
 const scalarField sZAll(gatherProc(sZ))
 const scalar dlt = delta_
 auto nearest = [dlt](const scalar d, const label M)
 {
 label i = label(floor(d/dlt))
 if (d - i*dlt > 0.5*dlt)
 {
 ++i
 }
 return min(max(i, label(0)), M - 1)
 }
 yindices_.setSize(sYAll.size)
 zindices_.setSize(sZAll.size)
 forAll(sYAll, I)
 {
 yindices_[I] = nearest(sYAll[I] - originY_, My_)
 zindices_[I] = nearest(sZAll[I] - originZ_, Mz_)
 }

 const label nTot = sYAll.size
 indicesPerProc_ = nTot/Pstream::nProcs
 rest_ = nTot - indicesPerProc_*Pstream::nProcs
 Info<< "turbulentDFMVeerInlet " << patch.name << ": " << nTot
 << " faces, virtual grid " << My_ << " x " << Mz_
 << ", delta = " << delta_ << endl
}


Foam::label Foam::turbulentDFMVeerInletFvPatchVectorField::nCells
(
 const scalar l
) const
{
 return max(label(1), label(ceil(l/delta_)))
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::localRange
(
 label& start
 label& nLocal
) const
{
 const label me = Pstream::myProcNo
 if (me < rest_)
 {
 start = me*indicesPerProc_ + me
 nLocal = indicesPerProc_ + 1
 }
 else
 {
 start = me*indicesPerProc_ + rest_
 nLocal = indicesPerProc_
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseFilterCoeff
{
 const tensorField L0All(gatherProc(L0_))
 ny_.setSize(L0All.size)
 nz_.setSize(L0All.size)
 nyMax_ = labelVector(1, 1, 1)
 nzMax_ = labelVector(1, 1, 1)
 forAll(L0All, I)
 {
 const tensor& L0 = L0All[I]
 // column 1: in-plane horizontal t, column 2: vertical
 ny_[I] = labelVector(nCells(L0.xy), nCells(L0.yy), nCells(L0.zy))
 nz_[I] = labelVector(nCells(L0.xz), nCells(L0.yz), nCells(L0.zz))
 for (direction c = 0; c < 3; c++)
 {
 nyMax_[c] = max(nyMax_[c], ny_[I][c])
 nzMax_[c] = max(nzMax_[c], nz_[I][c])
 }
 }

 label nyMaxAll = 0
 label nzMaxAll = 0
 for (direction c = 0; c < 3; c++)
 {
 rndSize_[c] =
 (My_ + 2*nfK_*nyMax_[c])*(Mz_ + 2*nfK_*nzMax_[c])
 nyMaxAll = max(nyMaxAll, nyMax_[c])
 nzMaxAll = max(nzMaxAll, nzMax_[c])
 }

 label start, nLocal
 localRange(start, nLocal)
 filterCoeff_.setSize(3)
 for (direction c = 0; c < 3; c++)
 {
 filterCoeff_[c].setSize(nLocal)
 for (label subI = 0; subI < nLocal; subI++)
 {
 const label I = start + subI
 get2DFilterCoeff(filterCoeff_[c][subI], ny_[I][c], nz_[I][c])
 }
 }

 Info<< "turbulentDFMVeerInlet " << patch.name
 << ": max filter widths ny = " << nyMax_ << ", nz = " << nzMax_
 << endl
 if (periodicInY_ && My_ < 2*nfK_*nyMaxAll)
 {
 WarningInFunction
 << "Filter half-width exceeds the periodic span in y" << endl
 }
 if (periodicInZ_ && Mz_ < 2*nfK_*nzMaxAll)
 {
 WarningInFunction
 << "Filter half-width exceeds the periodic span in z" << endl
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::get1DFilterCoeff
(
 scalarList& b
 const label n
) const
{
 if (n <= 0)
 {
 b.setSize(1)
 b[0] = 1.0
 return
 }

 const scalar pi = constant::mathematical::pi
 const label N = nfK_*n
 b.setSize(2*N + 1)
 scalar sum = 0
 for (label k = 0; k < 2*N + 1; k++)
 {
 const scalar r = scalar(k - N)
 if (filterType_ == "gaussian")
 {
 b[k] = exp(-pi*sqr(r)/(2.0*sqr(scalar(n))))
 }
 else if (filterType_ == "bessel")
 {
 b[k] = 0.1505857*bessk0(mag(1.0228626*r/n) + 0.0178114)
 }
 else
 {
 b[k] = exp(-mag(2.0*r/n))
 }

 sum += sqr(b[k])
 }

 sum = sqrt(sum)
 forAll(b, k)
 {
 b[k] /= sum
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::get2DFilterCoeff
(
 scalarList& filter
 const label ny
 const label nz
) const
{
 scalarList by
 scalarList bz
 get1DFilterCoeff(by, ny)
 get1DFilterCoeff(bz, nz)
 filter.setSize(by.size*bz.size)
 forAll(by, i)
 {
 forAll(bz, j)
 {
 filter[get1DIndex(i, j, bz.size)] = by[i]*bz[j]
 }
 }
}


Foam::scalarField
Foam::turbulentDFMVeerInletFvPatchVectorField::getRandomField
(
 const label totalSize
)
{
 List<scalarField> rndProc(Pstream::nProcs)
 const label n = totalSize/Pstream::nProcs
 const label rest = totalSize - n*Pstream::nProcs
 scalarField& myRnd = rndProc[Pstream::myProcNo]
 myRnd.setSize(Pstream::myProcNo < rest ? n + 1 : n)
 forAll(myRnd, i)
 {
 myRnd[i] = rndGen_.scalarNormal
 }

 Pstream::gatherList(rndProc)
 Pstream::scatterList(rndProc)
 return ListListOps::combine<scalarField>(rndProc, accessOp<scalarField>)
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::spatialCorr
{
 label start, nLocal
 localRange(start, nLocal)
 List<vectorField> filteredProc(Pstream::nProcs)
 filteredProc[Pstream::myProcNo].setSize(nLocal, vector::zero)
 vectorField& myFiltered = filteredProc[Pstream::myProcNo]
 for (direction c = 0; c < 3; c++)
 {
 scalarField rnd(getRandomField(rndSize_[c]))
 const label Ny = nfK_*nyMax_[c]
 const label Nz = nfK_*nzMax_[c]
 const label yDim = My_ + 2*Ny
 const label zDim = Mz_ + 2*Nz
 // Periodic padding: same copy order as TInF turbulentDFMInlet
 if (periodicInY_)
 {
 for (label i = 0; i < Ny; i++)
 {
 for (label k = 0; k < zDim; k++)
 {
 rnd[get1DIndex(i, k, zDim)] =
 rnd[get1DIndex(My_ + i, k, zDim)]
 rnd[get1DIndex(My_ + 2*Ny - i - 1, k, zDim)] =
 rnd[get1DIndex(2*Ny - i - 1, k, zDim)]
 }
 }
 }

 if (periodicInZ_)
 {
 for (label i = 0; i < yDim; i++)
 {
 for (label k = 0; k < Nz; k++)
 {
 rnd[get1DIndex(i, k, zDim)] =
 rnd[get1DIndex(i, Mz_ + k, zDim)]
 rnd[get1DIndex(i, Mz_ + Nz + k, zDim)] =
 rnd[get1DIndex(i, Nz + k, zDim)]
 }
 }
 }

 // 2D convolution for the faces handled by this processor
 forAll(myFiltered, subI)
 {
 const label I = start + subI
 const label Ky = nfK_*ny_[I][c]
 const label Kz = nfK_*nz_[I][c]
 const label wz = 2*Kz + 1
 const scalarList& coeff = filterCoeff_[c][subI]
 scalar sum = 0
 for (label ii = 0; ii <= 2*Ky; ii++)
 {
 const label row = yindices_[I] + Ny - Ky + ii
 const label rowStart =
 get1DIndex(row, zindices_[I] + Nz - Kz, zDim)
 const label cStart = ii*wz
 for (label jj = 0; jj < wz; jj++)
 {
 sum += rnd[rowStart + jj]*coeff[cStart + jj]
 }
 }

 myFiltered[subI][c] = sum
 }
 }

 Pstream::gatherList(filteredProc)
 Pstream::scatterList(filteredProc)
 const vectorField filteredAll
 (
 ListListOps::combine<vectorField>(filteredProc, accessOp<vectorField>)
)
 label offset = 0
 for (label i = 0; i < Pstream::myProcNo; i++)
 {
 offset += patchSize_[i]
 }

 forAll(uFluctFiltered_, facei)
 {
 uFluctFiltered_[facei] = filteredAll[offset + facei]
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::temporalCorr
{
 const scalar dt = db.time.deltaT.value
 forAll(uFluctTemporal_, facei)
 {
 // Convection speed along the local mean wind direction
 const scalar Uc = constMeanU_ ? Uref_ : U_[facei]
 for (direction c = 0; c < 3; c++)
 {
 // Unscaled along-wind scale L_{c x'} (TInF convention)
 const scalar Lt = L_[facei].component(3*c)
 scalar a = 0
 scalar b = 1
 if (Uc > vSmall && Lt > vSmall)
 {
 const scalar T = Lt/Uc
 a = exp(-dt/T)
 b = sqrt(1.0 - exp(-2.0*dt/T))
 }

 uFluctTemporal_[facei][c] =
 a*uFluctTemporalOld_[facei][c]
 + b*uFluctFiltered_[facei][c]
 }
 }

 uFluctTemporalOld_ = uFluctTemporal_
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::writeSamples
{
 if (outputFaces_.empty)
 {
 return
 }

 if (outputFiles_.empty)
 {
 const fileName dir
 (
 db.time.path/"postProcessing"/"turbulentDFMVeerInlet"
 /patch.name/db.time.timeName
)
 mkDir(dir)
 outputFiles_.setSize(outputFaces_.size)
 forAll(outputFaces_, i)
 {
 const label f = outputFaces_[i]
 std::string fname = "face" + std::string(Foam::name(f))
 if (Pstream::parRun)
 {
 fname +=
 "_proc" + std::string(Foam::name(Pstream::myProcNo))
 }
 fname += ".dat"
 outputFiles_.set(i, new OFstream(dir/word(fname)))
 OFstream& os = outputFiles_[i]
 os.precision(12)
 os << "# face " << f << nl
 << "# Cf " << patch.Cf[f] << nl
 << "# U " << U_[f] << nl
 << "# Uconv " << (constMeanU_ ? Uref_ : U_[f]) << nl
 << "# psi " << psi_[f] << nl
 << "# R " << R_[f] << nl
 << "# L " << L_[f] << nl
 << "# Leff " << Leff_[f] << nl
 << "# L0 " << L0_[f] << nl
 << "# delta " << delta_ << nl
 << "# columns: time ux uy uz" << endl
 }
 }

 const vectorField& Up = *this
 forAll(outputFaces_, i)
 {
 const vector& u = Up[outputFaces_[i]]
 outputFiles_[i]
 << db.time.value << ' '
 << u.x << ' ' << u.y << ' ' << u.z << endl
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialise
{
 const label n = patch.size
 eMean_.setSize(n)
 Q_.setSize(n)
 Lund_.setSize(n)
 Leff_.setSize(n)
 L0_.setSize(n)
 uFluctFiltered_.setSize(n, vector::zero)
 uFluctTemporalOld_.setSize(n, vector::zero)
 uFluctTemporal_.setSize(n, vector::zero)
 // Keep only valid local output faces
 DynamicList<label> valid
 forAll(outputFaces_, i)
 {
 if (outputFaces_[i] >= 0 && outputFaces_[i] < n)
 {
 valid.append(outputFaces_[i])
 }
 }
 if (valid.size != outputFaces_.size && !Pstream::parRun)
 {
 WarningInFunction
 << "Some outputFaceIndices are out of range and ignored" << endl
 }
 outputFaces_ = valid
 outputFiles_.clear
 calcGeometry
 initialiseFrames
 initialiseParameters
 initialiseVirtualGrid
 initialiseFilterCoeff
 if (isRestart_ && !isCleanRestart_)
 {
 uFluctTemporalOld_ = uFluctTemporal_
 }
 else
 {
 spatialCorr
 uFluctTemporalOld_ = uFluctFiltered_
 }

 isInitialized_ = true
 Info<< "turbulentDFMVeerInlet " << patch.name
 << ": initialised, psi range [" << gMin(psi_) << ", "
 << gMax(psi_) << "] deg" << endl
}


// * * * * * * * * * * * * * * * * Constructors * * * * * * * * * * * * * * //

Foam::turbulentDFMVeerInletFvPatchVectorField::
turbulentDFMVeerInletFvPatchVectorField
(
 const fvPatch& p
 const DimensionedField<vector, volMesh>& iF
)
:
 fixedValueFvPatchVectorField(p, iF)
 periodicInY_(false)
 periodicInZ_(false)
 constMeanU_(false)
 Uref_(10.0)
 gridFactor_(1.0)
 nfK_(2)
 filterType_("exponential")
 correctFlux_(true)
 seed_(-1)
 isCleanRestart_(false)
 outputFaces_
 vertical_(0, 0, 1)
 patchNormal_(1, 0, 0)
 tangent_(0, 1, 0)
 patchSize_(Pstream::nProcs, 0)
 U_(p.size, 0.0)
 R_(p.size, symmTensor::zero)
 L_(p.size, tensor::zero)
 psi_(p.size, 0.0)
 eMean_(p.size, vector::zero)
 Q_(p.size, tensor::I)
 Lund_(p.size, tensor::zero)
