namespace
{

//- Tensor component (row i = velocity component, column j = direction)
inline Foam::scalar tcmpt(const Foam::tensor& T, const int i, const int j)
{
 return T.component(Foam::direction(3*i + j))
}


//- Integral scale along m = s e_x' + c e_y' for an ellipsoidal correlation
// with scales Lx (along x') and Ly (along y'):
// L_m = [ (s/Lx)^2 + (c/Ly)^2 ]^(-1/2)
// Returns Ly / Lx exactly if s / c vanishes (psi = 0 identical to original).
Foam::scalar projectedScale
(
 const Foam::scalar s
 const Foam::scalar c
 const Foam::scalar Lx
 const Foam::scalar Ly
)
{
 const Foam::scalar eps = 1e-12
 if (std::fabs(s) <= eps)
 {
 return Ly > 0 ? Ly : 0.0
 }
 if (std::fabs(c) <= eps)
 {
 return Lx > 0 ? Lx : 0.0
 }
 if (Lx <= Foam::vSmall || Ly <= Foam::vSmall)
 {
 return 0.0
 }

 return 1.0/std::sqrt((s/Lx)*(s/Lx) + (c/Ly)*(c/Ly))
}


Foam::scalar bessi0(const Foam::scalar x)
{
 Foam::scalar ax, ans, y
 if ((ax = std::fabs(x)) < 3.75)
 {
 y = x/3.75
 y = y*y
 ans = 1.0 + y*(3.5156229 + y*(3.0899424 + y*(1.2067492
 + y*(0.2659732 + y*(0.360768e-1 + y*0.45813e-2)))))
 }
 else
 {
 y = 3.75/ax
 ans = (std::exp(ax)/std::sqrt(ax))*(0.39894228 + y*(0.-1
 + y*(0.225319e-2 + y*(-0.157565e-2 + y*(0.916281e-2
 + y*(-0.-1 + y*(0.-1 + y*(-0.-1
 + y*0.392377e-2))))))))
 }

 return ans
}


Foam::scalar bessk0(const Foam::scalar x)
{
 Foam::scalar y, ans
 if (x <= 2.0)
 {
 y = x*x/4.0
 ans = (-std::log(x/2.0)*bessi0(x)) + (-0.57721566 + y*(0.42278420
 + y*(0.23069756 + y*(0.-1 + y*(0.262698e-2
 + y*(0.10750e-3 + y*0.74e-5))))))
 }
 else
 {
 y = 2.0/x
 ans = (std::exp(-x)/std::sqrt(x))*(1.25331414 + y*(-0.-1
 + y*(0.-1 + y*(-0.-1 + y*(0.587872e-2
 + y*(-0.251540e-2 + y*0.53208e-3))))))
 }

 return ans
}

