void Foam::turbulentDFMVeerInletFvPatchVectorField::readProfiles
(
 const dictionary& dict
)
{
 const label n = patch.size
 if (dict.found("U"))
 {
 U_ = scalarField("U", dict, n)
 }
 else
 {
 U_ = interpolateProfile<scalar>("U", 0.0, false)
 }

 if (dict.found("R"))
 {
 R_ = symmTensorField("R", dict, n)
 }
 else
 {
 R_ = interpolateProfile<symmTensor>
 (
 "R", pTraits<symmTensor>::zero, false
)
 }

 if (dict.found("L"))
 {
 L_ = tensorField("L", dict, n)
 }
 else
 {
 L_ = interpolateProfile<tensor>("L", pTraits<tensor>::zero, false)
 }

 if (dict.found("psi"))
 {
 psi_ = scalarField("psi", dict, n)
 }
 else
 {
 psi_ = interpolateProfile<scalar>("psi", 0.0, true)
 }
}


Foam::tensor Foam::turbulentDFMVeerInletFvPatchVectorField::cholesky
(
 const symmTensor& R
 const point& pt
) const
{
 tensor B(Zero)
 if (R.xx <= 0)
 {
 FatalErrorInFunction
 << "R'xx <= 0 at face centre " << pt << ": R' = " << R
 << exit(FatalError)
 }

 B.xx = Foam::sqrt(R.xx)
 B.yx = R.xy/B.xx
 B.zx = R.xz/B.xx
 const scalar syy = R.yy - sqr(B.yx)
 if (syy <= 0)
 {
 FatalErrorInFunction
 << "R' not positive definite (yy pivot) at " << pt
 << ": R' = " << R << exit(FatalError)
 }

 B.yy = Foam::sqrt(syy)
 B.zy = (R.yz - B.yx*B.zx)/B.yy
 const scalar szz = R.zz - sqr(B.zx) - sqr(B.zy)
 if (szz <= 0)
 {
 FatalErrorInFunction
 << "R' not positive definite (zz pivot) at " << pt
 << ": R' = " << R << exit(FatalError)
 }

 B.zz = Foam::sqrt(szz)
 return B
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::procRange
(
 label& start
 label& size
) const
{
 const label p = Pstream::myProcNo
 if (p < rest_)
 {
 start = p*indicesPerProc_ + p
 size = indicesPerProc_ + 1
 }
 else
 {
 start = p*indicesPerProc_ + rest_
 size = indicesPerProc_
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialisePatch
{
 const vectorField nf(patch.nf)
 patchNormal_ = -gAverage(nf)
 const scalar magN = mag(patchNormal_)
 if (magN < small)
 {
 FatalErrorInFunction
 << "Cannot determine the normal of patch " << patch.name
 << exit(FatalError)
 }

 patchNormal_ /= magN
 for (direction d = 0; d < vector::nComponents; d++)
 {
 if (mag(patchNormal_.component(d)) <= small)
 {
 patchNormal_.component(d) = 0
 }
 }

 if (gMax(magSqr(patchNormal_ + nf)) > small)
 {
 WarningInFunction
 << "Patch " << patch.name << " is not planar" << endl
 }

 const vector zHat(0, 0, 1)
 horizNormal_ = patchNormal_ - (patchNormal_ & zHat)*zHat
 if (mag(horizNormal_) < small)
 {
 FatalErrorInFunction
 << "Patch " << patch.name << " is horizontal; psi about +z "
 << "is undefined" << exit(FatalError)
 }

 horizNormal_ /= mag(horizNormal_)
 patchTangent_ = zHat ^ horizNormal_
 if (mag(mag(patchNormal_.x) - 1.0) > 1e-6)
 {
 WarningInFunction
 << "Patch normal " << patchNormal_ << " is not +-x; the virtual "
 << "grid uses global y/z indices" << endl
 }

 patchSize_ = 0
 patchSize_[Pstream::myProcNo] = patch.size
 Pstream::gatherList(patchSize_)
 Pstream::scatterList(patchSize_)
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseParameters
{
 const vectorField& Cf = patch.Cf
 const scalar deg2rad = constant::mathematical::pi/180.0
 const vector zHat(0, 0, 1)
 label nLarge = 0
 label nFallback = 0
 label nBadU = 0
 forAll(U_, facei)
 {
 if (mag(psi_[facei]) >= 90.0)
 {
 nLarge++
 }

 // Local wind frame
 const scalar a = psi_[facei]*deg2rad
 const vector ex = Foam::cos(a)*horizNormal_ + Foam::sin(a)*patchTangent_
 const vector ey = zHat ^ ex
 const vector ez = zHat
 meanDir_[facei] = ex
 // Q has e_x', e_y', e_z' as columns: u_global = Q & u_local
 const tensor Q(tensor(ex, ey, ez).T)
 // Lund coefficients in the local frame
 const symmTensor& R = R_[facei]
 const tensor B(cholesky(R, Cf[facei]))
 Lund_[facei] = B
 LundGlobal_[facei] = Q & B
 // Mixing correction of the filter length scales (local frame)
 const tensor sqrB(cmptMultiply(B, B))
 const tensor E(sqrB.x/R.xx, sqrB.y/R.yy, sqrB.z/R.zz)
 tensor L0(inv(E) & L_[facei])
 bool negative = false
 for (direction d = 0; d < tensor::nComponents; d++)
 {
 if (L0.component(d) < 0)
 {
 negative = true
 break
 }
 }

 if (negative)
 {
 L0 = L_[facei]
 nFallback++
 }

 L0_[facei] = L0
 // Projection of the in-plane tangent on the local axes
 const scalar s = patchTangent_ & ex; // = sin(psi)
 const scalar c = patchTangent_ & ey; // = cos(psi)

 const tensor& Lt = scaleTimeScales_ ? L0 : L_[facei]
 const scalar Uc = constMeanU_ ? Uref_ : U_[facei]
 if (Uc <= vSmall)
 {
 nBadU++
 }

 vector Ly, Lz, T
 for (int k = 0; k < 3; k++)
 {
 Ly.component(k) =
 projectedScale(s, c, tcmpt(L0, k, 0), tcmpt(L0, k, 1))
 Lz.component(k) = max(tcmpt(L0, k, 2), 0.0)
 T.component(k) =
 Uc > vSmall ? max(tcmpt(Lt, k, 0), 0.0)/Uc : 0.0
 }

 Lfy_[facei] = Ly
 Lfz_[facei] = Lz
 timeScale_[facei] = T
 }

 reduce(nLarge, sumOp<label>)
 reduce(nFallback, sumOp<label>)
 reduce(nBadU, sumOp<label>)
 if (nLarge)
 {
 WarningInFunction
 << nLarge << " faces have |psi| >= 90 deg (no net inflow)" << endl
 }

 if (nBadU)
 {
 WarningInFunction
 << nBadU << " faces have non-positive convection speed; "
 << "white noise in time is used there" << endl
 }

 Info<< "turbulentDFMVeerInlet " << patch.name << ": " << nFallback
 << " faces fell back to L0 = L (negative inv(E)&L)" << endl
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseVirtualGrid
{
 boundBox patchBounds(patch.Cf)
 origin_ = patchBounds.min
 delta_ = Foam::sqrt(gMin(patch.magSf))/gridFactor_
 My_ = label(std::ceil(patchBounds.span.component(vector::Y)/delta_)) + 1
 Mz_ = label(std::ceil(patchBounds.span.component(vector::Z)/delta_)) + 1
 vectorField Cf(gatherProc(vectorField(patch.Cf)))
 Cf -= origin_
 yindices_.setSize(Cf.size)
 zindices_.setSize(Cf.size)
 forAll(Cf, facei)
 {
 const scalar distY = Cf[facei].component(vector::Y)
 const scalar distZ = Cf[facei].component(vector::Z)
 yindices_[facei] = label(std::floor(distY/delta_))
 zindices_[facei] = label(std::floor(distZ/delta_))
 const scalar remY = distY - std::floor(distY/delta_)*delta_
 const scalar remZ = distZ - std::floor(distZ/delta_)*delta_
 if (remY > delta_/2)
 {
 yindices_[facei] += 1
 }
 if (remZ > delta_/2)
 {
 zindices_[facei] += 1
 }
 }

 indicesPerProc_ = 0
 rest_ = 0
 if (Pstream::master)
 {
 indicesPerProc_ = Cf.size/Pstream::nProcs
 rest_ = Cf.size - indicesPerProc_*Pstream::nProcs
 Info<< "turbulentDFMVeerInlet: " << Cf.size << " faces, virtual "
 << "grid " << My_ << " x " << Mz_ << ", delta = " << delta_
 << endl
 }

 Pstream::scatter(indicesPerProc_)
 Pstream::scatter(rest_)
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseFilterCoeff
{
 const vectorField Ly(gatherProc(Lfy_))
 const vectorField Lz(gatherProc(Lfz_))
 ny_.setSize(Ly.size)
 nz_.setSize(Ly.size)
 forAll(Ly, I)
 {
 for (direction c = 0; c < 3; c++)
 {
 ny_[I].component(c) =
 label(std::ceil(Ly[I].component(c)/delta_))
 nz_[I].component(c) =
 label(std::ceil(Lz[I].component(c)/delta_))
 }
 }

 const labelVector nyMax = gMax(ny_)
 const labelVector nzMax = gMax(nz_)
 for (direction c = 0; c < 3; c++)
 {
 rndSize_.component(c) =
 (My_ + 2*nfK_*nyMax.component(c))
 *(Mz_ + 2*nfK_*nzMax.component(c))
 if (periodicInY_ && My_ < nfK_*nyMax.component(c))
 {
 WarningInFunction
 << "periodicInY: filter half width " << nfK_*nyMax.component(c)
 << " exceeds the virtual grid width " << My_ << endl
 }
 if (periodicInZ_ && Mz_ < nfK_*nzMax.component(c))
 {
 WarningInFunction
 << "periodicInZ: filter half width " << nfK_*nzMax.component(c)
 << " exceeds the virtual grid height " << Mz_ << endl
 }
 }

 Info<< "turbulentDFMVeerInlet: random field sizes " << rndSize_ << endl
 label start, size
 procRange(start, size)
 for (direction c = 0; c < 3; c++)
 {
 filterCoeff_[c].setSize(size)
 }

 for (label subI = 0; subI < size; subI++)
 {
 const label I = subI + start
 for (direction c = 0; c < 3; c++)
 {
 get2DFilterCoeff
 (
 filterCoeff_[c][subI]
 ny_[I].component(c)
 nz_[I].component(c)
)
 }
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::get1DFilterCoeff
(
 scalarList& b
 const label n
) const
{
 // n = 0 (zero length scale): unit impulse, i.e. unit-variance white
 // noise (the original returned a zero coefficient here)
 if (n <= 0)
 {
 b.setSize(1)
 b[0] = 1.0
 return
 }

 const scalar pi = constant::mathematical::pi
 const label N = nfK_*n
 b.setSize(2*N + 1)
 scalar sum = 0
 for (label k = 0; k < 2*N + 1; k++)
 {
 const scalar d = scalar(k - N)
 if (filterType_ == "exponential")
 {
 b[k] = Foam::exp(-mag(2.0*d/n))
 }
 else if (filterType_ == "gaussian")
 {
 b[k] = Foam::exp(-pi*sqr(d)/(2.0*sqr(scalar(n))))
 }
 else
 {
 b[k] = 0.1505857*bessk0(mag(1.0228626*d/n) + 0.0178114)
 }

 sum += sqr(b[k])
 }

 sum = Foam::sqrt(sum)
 forAll(b, k)
 {
 b[k] /= sum
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::get2DFilterCoeff
(
 scalarList& filter
 const label ny
 const label nz
) const
{
 scalarList by, bz
 get1DFilterCoeff(by, ny)
 get1DFilterCoeff(bz, nz)
 filter.setSize(by.size*bz.size)
 forAll(by, i)
 {
 forAll(bz, j)
 {
 filter[i*bz.size + j] = by[i]*bz[j]
 }
 }
}


Foam::scalarField
Foam::turbulentDFMVeerInletFvPatchVectorField::getRandomField
(
 const label totalSize
)
{
 List<scalarField> rp(Pstream::nProcs)
 const label size = totalSize/Pstream::nProcs
 const label rest = totalSize - size*Pstream::nProcs
 scalarField& mine = rp[Pstream::myProcNo]
 mine.setSize(Pstream::myProcNo < rest ? size + 1 : size)
 forAll(mine, i)
 {
 mine[i] = rndGen_.scalarNormal
 }

 Pstream::gatherList(rp)
 Pstream::scatterList(rp)
 return ListListOps::combine<scalarField>(rp, accessOp<scalarField>)
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::spatialCorr
{
 const labelVector nyMax = gMax(ny_)
 const labelVector nzMax = gMax(nz_)
 List<scalarField> rnd(3)
 labelVector offY, offZ, rowLen
 for (direction c = 0; c < 3; c++)
 {
 offY.component(c) = nfK_*nyMax.component(c)
 offZ.component(c) = nfK_*nzMax.component(c)
 rowLen.component(c) = Mz_ + 2*offZ.component(c)
 const label oy = offY.component(c)
 const label oz = offZ.component(c)
 const label rl = rowLen.component(c)
 const label nRows = My_ + 2*oy
 rnd[c] = getRandomField(rndSize_.component(c))
 scalarField& f = rnd[c]
 if (periodicInY_)
 {
 for (label i = 0; i < oy; i++)
 {
 for (label k = 0; k < rl; k++)
 {
 f[i*rl + k] = f[(My_ + i)*rl + k]
 f[(My_ + 2*oy - i - 1)*rl + k] = f[(2*oy - i - 1)*rl + k]
 }
 }
 }

 if (periodicInZ_)
 {
 for (label r = 0; r < nRows; r++)
 {
 const label b = r*rl
 for (label k = 0; k < oz; k++)
 {
 f[b + k] = f[b + Mz_ + k]
 f[b + Mz_ + oz + k] = f[b + oz + k]
 }
 }
 }
 }

 label start, size
 procRange(start, size)
 List<vectorField> filteredProc(Pstream::nProcs)
 filteredProc[Pstream::myProcNo].setSize(size, vector::zero)
 for (label subI = 0; subI < size; subI++)
 {
 const label I = subI + start
 const label i = yindices_[I]
 const label j = zindices_[I]
 vector u(Zero)
 for (direction c = 0; c < 3; c++)
 {
 const label Ny = nfK_*ny_[I].component(c)
 const label Nz = nfK_*nz_[I].component(c)
 const label nzW = 2*Nz + 1
 const scalarField& f = rnd[c]
 const scalarList& filt = filterCoeff_[c][subI]
 scalar s = 0
 for (label ii = 0; ii <= 2*Ny; ii++)
 {
 const label base =
 (i + offY.component(c) - Ny + ii)*rowLen.component(c)
 + (j + offZ.component(c) - Nz)
 const label fb = ii*nzW
 for (label jj = 0; jj < nzW; jj++)
 {
 s += f[base + jj]*filt[fb + jj]
 }
 }

 u.component(c) = s
 }

 filteredProc[Pstream::myProcNo][subI] = u
 }

 Pstream::gatherList(filteredProc)
 Pstream::scatterList(filteredProc)
 const vectorField filtered
 (
 ListListOps::combine<vectorField>(filteredProc, accessOp<vectorField>)
)
 label offset = 0
 for (label p = 0; p < Pstream::myProcNo; p++)
 {
 offset += patchSize_[p]
 }

 if (patchSize_[Pstream::myProcNo] > 0)
 {
 uFluctFiltered_ =
 SubField<vector>(filtered, patchSize_[Pstream::myProcNo], offset)
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::temporalCorr
{
 const scalar dt = db.time.deltaTValue
 forAll(uFluctTemporal_, facei)
 {
 for (direction c = 0; c < 3; c++)
 {
 const scalar T = timeScale_[facei].component(c)
 const scalar a = (T > vSmall) ? Foam::exp(-dt/T) : 0.0
 uFluctTemporal_[facei].component(c) =
 a*uFluctTemporalOld_[facei].component(c)
 + Foam::sqrt(max(1.0 - a*a, 0.0))
 *uFluctFiltered_[facei].component(c)
 }
 }

 uFluctTemporalOld_ = uFluctTemporal_
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialise
{
 const label n = patch.size
 meanDir_.setSize(n)
 Lund_.setSize(n)
 LundGlobal_.setSize(n)
 L0_.setSize(n)
 Lfy_.setSize(n)
 Lfz_.setSize(n)
 timeScale_.setSize(n)
 uFluctFiltered_.setSize(n)
 uFluctFiltered_ = vector::zero
 uFluctTemporalOld_.setSize(n)
 if (uFluctTemporal_.size != n)
 {
 uFluctTemporal_.setSize(n)
 uFluctTemporal_ = vector::zero
 isRestart_ = false
 }

 initialisePatch
 initialiseParameters
 initialiseVirtualGrid
 initialiseFilterCoeff
 if (isRestart_ && !isCleanRestart_)
 {
 uFluctTemporalOld_ = uFluctTemporal_
 }
 else
 {
 spatialCorr
 uFluctTemporalOld_ = uFluctFiltered_
 }

 Info<< "turbulentDFMVeerInlet " << patch.name
 << ": initialisation complete" << endl
}


