void Foam::turbulentDFMVeerInletFvPatchVectorField::rmap
(
 const fvPatchField<vector>& ptf
 const labelList& addr
)
{
 fixedValueFvPatchVectorField::rmap(ptf, addr)
 const turbulentDFMVeerInletFvPatchVectorField& tiptf =
 refCast<const turbulentDFMVeerInletFvPatchVectorField>(ptf)
 uFluctTemporal_.rmap(tiptf.uFluctTemporal_, addr)
 U_.rmap(tiptf.U_, addr)
 R_.rmap(tiptf.R_, addr)
 L_.rmap(tiptf.L_, addr)
 psi_.rmap(tiptf.psi_, addr)
 isInitialized_ = false
}


