void Foam::turbulentDFMVeerInletFvPatchVectorField::updateCoeffs
{
 if (updated)
 {
 return
 }

 if (!initialised_)
 {
 initialise
 }

 const label ti = db.time.timeIndex
 if (ti != curTimeIndex_)
 {
 const scalar t = db.time.value
 const scalar dt = t - lastTime_
 if (dt > 0)
 {
 advance(dt)
 lastTime_ = t
 if (useDelay_)
 {
 pushPlane(t)
 }
 }
 curTimeIndex_ = ti
 }

 vectorField Up(patch.size)
 forAll(Up, f)
 {
 const vectorField& P =
 useDelay_ ? plane(nearestAge(lastTime_ - faceDelay_[f])) : Psi_
 Up[f] = Umean_[f] + (M_[f] & P[faceNode_[f]])
 }

 fixedValueFvPatchVectorField::operator==(Up)
 fixedValueFvPatchVectorField::updateCoeffs
}


