#include "turbulentDFMVeerInletFvPatchVectorField.H"
#include "addToRunTimeSelectionTable.H"
#include "fvPatchFieldMapper.H"
#include "volFields.H"
#include "surfaceFields.H"
#include "IFstream.H"
#include "OSspecific.H"
#include "mathematicalConstants.H"

#include <algorithm>
#include <numeric>
#include <vector>
#include <cmath>

// * * * * * * * * * * * * * * * Local helpers * * * * * * * * * * * * * * //

namespace Foam
{
namespace dfmVeer
{

static std::vector<scalar> uniqueLevels(std::vector<scalar> v, const scalar tol)
{
 std::sort(v.begin, v.end)
 std::vector<scalar> lev
 std::size_t i = 0
 while (i < v.size)
 {
 const scalar start = v[i]
 scalar sum = 0
 label n = 0
 while (i < v.size && v[i] - start <= tol)
 {
 sum += v[i]; ++n; ++i
 }
 lev.push_back(sum/n)
 }
 return lev
}


static void locate
(
 const scalarField& lev, const scalar x, const bool periodic
 const scalar period, label& i0, label& i1, scalar& w
)
{
 const label n = lev.size
 if (n <= 1) { i0 = 0; i1 = 0; w = 0; return; }

 const scalar* b = lev.cdata
 const label up = label(std::upper_bound(b, b + n, x) - b)
 if (up == 0 || up == n)
 {
 if (periodic)
 {
 i0 = n - 1
 i1 = 0
 const scalar gap = period - (lev[n-1] - lev[0])
 const scalar xl = (up == 0) ? lev[n-1] - period : lev[n-1]
 w = (x - xl)/max(gap, vSmall)
 }
 else
 {
 i0 = (up == 0) ? 0 : n - 1
 i1 = i0
 w = 0
 }
 }
 else
 {
 i0 = up - 1
 i1 = up
 w = (x - lev[i0])/max(lev[i1] - lev[i0], vSmall)
 }
 w = min(max(w, scalar(0)), scalar(1))
}


template<class Type>
static Type interpZ(const scalarField& zs, const Field<Type>& f, const scalar z)
{
 const label n = zs.size
 if (n == 1 || z <= zs[0]) return f[0]
 if (z >= zs[n-1]) return f[n-1]
 const scalar* b = zs.cdata
 const label up = label(std::upper_bound(b, b + n, z) - b)
 const label lo = up - 1
 const scalar w = (z - zs[lo])/max(zs[up] - zs[lo], vSmall)
 return (1 - w)*f[lo] + w*f[up]
}


static tensor choleskyLower(const symmTensor& R)
{
 const scalar a11 = Foam::sqrt(max(R.xx, scalar(0)))
 const scalar a21 = (a11 > vSmall) ? R.xy/a11 : scalar(0)
 const scalar a31 = (a11 > vSmall) ? R.xz/a11 : scalar(0)
 const scalar a22 = Foam::sqrt(max(R.yy - sqr(a21), scalar(0)))
 const scalar a32 = (a22 > vSmall) ? (R.yz - a21*a31)/a22 : scalar(0)
 const scalar a33 =
 Foam::sqrt(max(R.zz - sqr(a31) - sqr(a32), scalar(0)))
 return tensor(a11, 0, 0, a21, a22, 0, a31, a32, a33)
}


// AR(1) exponential filter along a line; a[j] links j-1 -> j
// a[0] = wrap link (periodic only). Unit variance in -> unit variance out.
static void arFilterLine(scalarList& x, const scalarList& a, const bool periodic)
{
 const label n = x.size
 if (n <= 1) return
 if (!periodic)
 {
 for (label j = 1; j < n; ++j)
 {
 const scalar aj = a[j]
 x[j] = aj*x[j-1] + Foam::sqrt(max(1 - aj*aj, scalar(0)))*x[j]
 }
 }
 else
 {
 scalarList p(n), g(n)
 scalar prevP = 0, prevG = 1
 for (label j = 0; j < n; ++j)
 {
 const scalar aj = a[j]
 p[j] = aj*prevP + Foam::sqrt(max(1 - aj*aj, scalar(0)))*x[j]
 g[j] = aj*prevG
 prevP = p[j]
 prevG = g[j]
 }
 const scalar A = min(g[n-1], scalar(1 - 1e-12))
 const scalar phiLast = p[n-1]/(1 - A)
 const scalar norm = Foam::sqrt((1 - A)/(1 + A))
 for (label j = 0; j < n; ++j) x[j] = norm*(p[j] + g[j]*phiLast)
 }
}

} // End namespace dfmVeer
} // End namespace Foam


// * * * * * * * * * * * * * Private Member Functions * * * * * * * * * * * //

void Foam::turbulentDFMVeerInletFvPatchVectorField::readProfiles
{
 const fileName dir
 (
 this->db.time.constant/"boundaryData"/this->patch.name
)
 const word names[5] = {"points", "U", "R", "L", "psi"}
 for (const word& n : names)
 {
 if (!isFile(dir/n))
 {
 FatalErrorInFunction
 << "Cannot find inlet profile file " << dir/n
 << exit(FatalError)
 }
 }

 IFstream isP(dir/"points"); const pointField pts(isP)
 IFstream isU(dir/"U"); const scalarField Uin(isU)
 IFstream isR(dir/"R"); const symmTensorField Rin(isR)
 IFstream isL(dir/"L"); const tensorField Lin(isL)
 IFstream isPsi(dir/"psi"); const scalarField psiIn(isPsi)
 const label n = pts.size
 if
 (
 n == 0 || Uin.size != n || Rin.size != n
 || Lin.size != n || psiIn.size != n
)
 {
 FatalErrorInFunction
 << "Inconsistent sizes in " << dir << ": points " << n
 << " U " << Uin.size << " R " << Rin.size
 << " L " << Lin.size << " psi " << psiIn.size
 << exit(FatalError)
 }

 std::vector<label> order(n)
 std::iota(order.begin, order.end, label(0))
 std::stable_sort
 (
 order.begin, order.end
 [&pts](const label a, const label b) { return pts[a].z < pts[b].z; }
)
 const scalar span = pts[order[n-1]].z - pts[order[0]].z
 const scalar tol = 1e-6*max(span, scalar(1))
 std::vector<scalar> zs, Us, ps
 std::vector<symmTensor> Rs
 std::vector<tensor> Ls
 label i = 0
 while (i < n)
 {
 const scalar z0 = pts[order[i]].z
 scalar zS = 0, US = 0, pS = 0
 symmTensor RS(Zero)
 tensor LS(Zero)
 label m = 0
 while (i < n && pts[order[i]].z - z0 <= tol)
 {
 const label q = order[i]
 zS += pts[q].z; US += Uin[q]; pS += psiIn[q]
 RS += Rin[q]; LS += Lin[q]
 ++m; ++i
 }
 zs.push_back(zS/m)
 Us.push_back(US/m)
 ps.push_back(pS/m)
 Rs.push_back(RS/scalar(m))
 Ls.push_back(LS/scalar(m))
 }

 const label nl = zs.size
 zProf_.setSize(nl)
 UProf_.setSize(nl)
 psiProf_.setSize(nl)
 RProf_.setSize(nl)
 LProf_.setSize(nl)
 const scalar deg2rad = constant::mathematical::pi/180.0
 for (label k = 0; k < nl; ++k)
 {
 zProf_[k] = zs[k]
 UProf_[k] = Us[k]
 psiProf_[k] = ps[k]*deg2rad
 RProf_[k] = Rs[k]
 LProf_[k] = Ls[k]
 }

 Info<< "turbulentDFMVeerInlet [" << this->patch.name << "]: read "
 << n << " profile points -> " << nl << " height levels, z in ["
 << zProf_[0] << ", " << zProf_[nl-1] << "], psi in ["
 << min(psiProf_)/deg2rad << ", " << max(psiProf_)/deg2rad
 << "] deg" << endl
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialise
{
 readProfiles
 const vectorField& Cf = this->patch.Cf
 List<vectorField> allCf(Pstream::nProcs)
 allCf[Pstream::myProcNo] = Cf
 Pstream::gatherList(allCf)
 Pstream::scatterList(allCf)
 std::vector<scalar> ys, zs
 forAll(allCf, proci)
 {
 forAll(allCf[proci], fi)
 {
 ys.push_back(allCf[proci][fi].y)
 zs.push_back(allCf[proci][fi].z)
 }
 }
 const label nTot = ys.size
 if (nTot == 0)
 {
 ny_ = 0
 nz_ = 0
 initialised_ = true
 return
 }

 const pointField& lp = this->patch.patch.localPoints
 scalar yMin = great, yMax = -great, zMin = great, zMax = -great
 forAll(lp, pi)
 {
 yMin = min(yMin, lp[pi].y)
 yMax = max(yMax, lp[pi].y)
 zMin = min(zMin, lp[pi].z)
 zMax = max(zMax, lp[pi].z)
 }
 reduce(yMin, minOp<scalar>)
 reduce(yMax, maxOp<scalar>)
 reduce(zMin, minOp<scalar>)
 reduce(zMax, maxOp<scalar>)
 Wy_ = yMax - yMin
 Hz_ = zMax - zMin
 const scalar hMin = Foam::sqrt(gMin(this->patch.magSf))
 const scalar tol = 1e-3*hMin
 std::vector<scalar> yl = dfmVeer::uniqueLevels(ys, tol)
 std::vector<scalar> zl = dfmVeer::uniqueLevels(zs, tol)
 const bool structured = (label(yl.size*zl.size) == nTot)
 if (!structured)
 {
 const scalar h = Foam::sqrt(gSum(this->patch.magSf)/nTot)
 const label nyv = max(label(2), label(std::ceil(2*Wy_/h)))
 const label nzv = max(label(2), label(std::ceil(2*Hz_/h)))
 yl.resize(nyv)
 zl.resize(nzv)
 for (label j = 0; j < nyv; ++j) yl[j] = yMin + (j + 0.5)*Wy_/nyv
 for (label k = 0; k < nzv; ++k) zl[k] = zMin + (k + 0.5)*Hz_/nzv
 WarningInFunction
 << "Patch " << this->patch.name << " is not a structured "
 << "y-z grid; using a uniform virtual grid " << nyv << " x "
 << nzv << " with bilinear interpolation to the faces." << endl
 }

 ny_ = yl.size
 nz_ = zl.size
 yv_.setSize(ny_)
 zv_.setSize(nz_)
 forAll(yv_, j) yv_[j] = yl[j]
 forAll(zv_, k) zv_[k] = zl[k]
 scalarField gy(ny_, 0), gz(nz_, 0)
 for (label j = 1; j < ny_; ++j) gy[j] = yv_[j] - yv_[j-1]
 for (label k = 1; k < nz_; ++k) gz[k] = zv_[k] - zv_[k-1]
 gy[0] = max(Wy_ - (yv_[ny_-1] - yv_[0]), vSmall)
 gz[0] = max(Hz_ - (zv_[nz_-1] - zv_[0]), vSmall)
 const scalar Uscale = max(Uref_, max(UProf_))
 const scalar Umin = max(1e-3*Uscale, scalar(1e-6))
 const scalar lMin = 1e-6
 const scalar aMax = 1 - 1e-10
 aY_.setSize(ny_*nz_)
 aZ_.setSize(nz_)
 Tv_.setSize(nz_)
 vectorField LzNode(nz_)
 label nClipped = 0
 forAll(zv_, k)
 {
 const scalar z = zv_[k]
 const scalar U = dfmVeer::interpZ(zProf_, UProf_, z)
 const scalar psi = dfmVeer::interpZ(zProf_, psiProf_, z)
 const tensor L = dfmVeer::interpZ(zProf_, LProf_, z)
 const scalar Uc = max(U, Umin)
 const scalar c = mag(Foam::cos(psi))
 const scalar s = mag(Foam::sin(psi))
 const vector Lx(L.xx, L.yx, L.zx)
 const vector Ly(L.xy, L.yy, L.zy)
 const vector Lz(L.xz, L.yz, L.zz)
 vector Lam(Zero)
 for (direction i = 0; i < 3; ++i)
 {
 const scalar lx = max(Lx[i], lMin)
 const scalar ly = max(Ly[i], lMin)
 const scalar lz = max(Lz[i], lMin)
 Tv_[k][i] = lx/Uc
 LzNode[k][i] = lz
 scalar lam = ly
 if (obliqueCorrection_)
 {
 const scalar inv = c/ly - s/lx
 const scalar invMin =
 max(c, scalar(1e-3))/(ly*maxYScaleRatio_)
 if (inv < invMin) ++nClipped
 lam = 1.0/max(inv, invMin)
 }
 Lam[i] = lam
 }

 for (label j = 0; j < ny_; ++j)
 {
 vector& ay = aY_[j + ny_*k]
 for (direction i = 0; i < 3; ++i)
 {
 ay[i] = min(Foam::exp(-gy[j]/Lam[i]), aMax)
 }
 }
 }

 forAll(zv_, k)
 {
 const label km = (k == 0) ? nz_ - 1 : k - 1
 const vector Lm = 0.5*(LzNode[k] + LzNode[km])
 for (direction i = 0; i < 3; ++i)
 {
 aZ_[k][i] = min(Foam::exp(-gz[k]/Lm[i]), aMax)
 }
 }

 if (nClipped)
 {
 WarningInFunction
 << "Oblique length-scale correction clipped at " << nClipped
 << " (level, component) pairs; Lambda limited to "
 << maxYScaleRatio_ << " L_y'/cos(psi)." << endl
 }

 const label nf = Cf.size
 fJ0_.setSize(nf)
 fJ1_.setSize(nf)
 fK0_.setSize(nf)
 fK1_.setSize(nf)
 fWy_.setSize(nf)
 fWz_.setSize(nf)
 fUmean_.setSize(nf)
 fM_.setSize(nf)
 forAll(Cf, f)
 {
 dfmVeer::locate
 (
 yv_, Cf[f].y, periodicInY_, Wy_, fJ0_[f], fJ1_[f], fWy_[f]
)
 dfmVeer::locate
 (
 zv_, Cf[f].z, periodicInZ_, Hz_, fK0_[f], fK1_[f], fWz_[f]
)
 const scalar z = Cf[f].z
 const scalar U = dfmVeer::interpZ(zProf_, UProf_, z)
 const scalar psi = dfmVeer::interpZ(zProf_, psiProf_, z)
 const symmTensor R = dfmVeer::interpZ(zProf_, RProf_, z)
 const scalar c = Foam::cos(psi)
 const scalar s = Foam::sin(psi)
 fUmean_[f] = vector(U*c, U*s, 0)
 const tensor Q(c, -s, 0, s, c, 0, 0, 0, 1)
 fM_[f] = Q & dfmVeer::choleskyLower(R)
 }

 spatialField(Phi_)
 initialised_ = true
 Info<< "turbulentDFMVeerInlet [" << this->patch.name << "]: "
 << (structured ? "structured" : "virtual") << " grid " << ny_
 << " x " << nz_ << ", periodicInY " << periodicInY_
 << ", periodicInZ " << periodicInZ_
 << ", obliqueCorrection " << obliqueCorrection_ << endl
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::spatialField
(
 vectorField& psi
)
{
 psi.setSize(ny_*nz_)
 forAll(psi, idx)
 {
 const scalar r0 = ndist_(gen_)
 const scalar r1 = ndist_(gen_)
 const scalar r2 = ndist_(gen_)
 psi[idx] = vector(r0, r1, r2)
 }

 scalarList lineY(ny_), aLineY(ny_), lineZ(nz_), aLineZ(nz_)
 for (direction i = 0; i < 3; ++i)
 {
 for (label k = 0; k < nz_; ++k)
 {
 for (label j = 0; j < ny_; ++j)
 {
 const label idx = j + ny_*k
 lineY[j] = psi[idx][i]
 aLineY[j] = aY_[idx][i]
 }
 dfmVeer::arFilterLine(lineY, aLineY, periodicInY_)
 for (label j = 0; j < ny_; ++j) psi[j + ny_*k][i] = lineY[j]
 }

 for (label k = 0; k < nz_; ++k) aLineZ[k] = aZ_[k][i]
 for (label j = 0; j < ny_; ++j)
 {
 for (label k = 0; k < nz_; ++k) lineZ[k] = psi[j + ny_*k][i]
 dfmVeer::arFilterLine(lineZ, aLineZ, periodicInZ_)
 for (label k = 0; k < nz_; ++k) psi[j + ny_*k][i] = lineZ[k]
 }
 }
}


