void Foam::turbulentDFMVeerInletFvPatchVectorField::checkSettings
(
 const dictionary& dict
) const
{
 if
 (
 filterType_ != "exponential"
 && filterType_ != "gaussian"
 && filterType_ != "bessel"
)
 {
 FatalIOErrorInFunction(dict)
 << "Unknown filterType " << filterType_
 << ". Valid: exponential gaussian bessel"
 << exit(FatalIOError)
 }

 if (nfK_ < 1)
 {
 FatalIOErrorInFunction(dict)
 << "filterFactor must be >= 1" << exit(FatalIOError)
 }

 if (gridFactor_ <= 0)
 {
 FatalIOErrorInFunction(dict)
 << "gridFactor must be > 0" << exit(FatalIOError)
 }

 if (constMeanU_ && Uref_ <= 0)
 {
 FatalIOErrorInFunction(dict)
 << "Uref must be > 0 when constMeanU is true"
 << exit(FatalIOError)
 }

 if (mag(vertical_) < small)
 {
 FatalIOErrorInFunction(dict)
 << "verticalAxis has zero length" << exit(FatalIOError)
 }
}


