template<class Type>
Foam::tmp<Foam::Field<Type>>
Foam::turbulentDFMVeerInletFvPatchVectorField::interpolateHeight
(
 const Field<Type>& sampleVals
 const word& fieldName
) const
{
 const fileName pointsFile(boundaryDataDir/"points")
 if (!isFile(pointsFile))
 {
 FatalErrorInFunction
 << "Cannot find " << pointsFile << exit(FatalError)
 }

 IFstream pis(pointsFile)
 const pointField samplePoints(pis)
 if (samplePoints.empty || samplePoints.size != sampleVals.size)
 {
 FatalErrorInFunction
 << "Field " << fieldName << " has " << sampleVals.size
 << " values but " << pointsFile << " has "
 << samplePoints.size << " points" << exit(FatalError)
 }

 const scalarField hs(samplePoints & vertical_)
 labelList order
 sortedOrder(hs, order)
 const scalar tol = 1e-6*(max(hs) - min(hs)) + 1e-9
 // Height profile: average samples sharing (nearly) the same height
 DynamicList<scalar> hProf
 DynamicList<Type> vProf
 label i = 0
 while (i < order.size)
 {
 const scalar h0 = hs[order[i]]
 scalar hSum = 0
 Type vSum = pTraits<Type>::zero
 label n = 0
 while (i < order.size && hs[order[i]] - h0 <= tol)
 {
 hSum += hs[order[i]]
 vSum += sampleVals[order[i]]
 ++n
 ++i
 }

 hProf.append(hSum/n)
 vProf.append(vSum/scalar(n))
 }

 const label np = hProf.size
 const scalarField hf(patch.Cf & vertical_)
 tmp<Field<Type>> tvals(new Field<Type>(hf.size, pTraits<Type>::zero))
 Field<Type>& vals = tvals.ref
 label nClamped = 0
 forAll(hf, facei)
 {
 const scalar h = hf[facei]
 if (np == 1 || h <= hProf[0])
 {
 if (np > 1 && h < hProf[0] - tol)
 {
 ++nClamped
 }
 vals[facei] = vProf[0]
 }
 else if (h >= hProf[np - 1])
 {
 if (h > hProf[np - 1] + tol)
 {
 ++nClamped
 }
 vals[facei] = vProf[np - 1]
 }
 else
 {
 label k = 0
 while (k < np - 2 && hProf[k + 1] <= h)
 {
 ++k
 }

 const scalar w = (h - hProf[k])/(hProf[k + 1] - hProf[k])
 vals[facei] = (1.0 - w)*vProf[k] + w*vProf[k + 1]
 }
 }

 reduce(nClamped, sumOp<label>)
 Info<< "turbulentDFMVeerInlet " << patch.name << ": " << fieldName
 << " interpolated in height from " << np << " levels" << endl
 if (nClamped)
 {
 WarningInFunction
 << nClamped << " faces of patch " << patch.name
 << " lie outside the height range of the " << fieldName
 << " profile; end values used" << endl
 }

 return tvals
}


template<class Type>
Foam::tmp<Foam::Field<Type>>
Foam::turbulentDFMVeerInletFvPatchVectorField::readProfile
(
 const word& fieldName
 const dictionary& dict
) const
{
 if (dict.found(fieldName))
 {
 return tmp<Field<Type>>
 (
 new Field<Type>(fieldName, dict, patch.size)
)
 }

 const fileName valsFile(boundaryDataDir/fieldName)
 if (!isFile(valsFile))
 {
 FatalIOErrorInFunction(dict)
 << "Neither keyword " << fieldName << " nor file " << valsFile
 << " found" << exit(FatalIOError)
 }

 IFstream is(valsFile)
 const Field<Type> sampleVals(is)
 return interpolateHeight(sampleVals, fieldName)
}


Foam::tmp<Foam::scalarField>
Foam::turbulentDFMVeerInletFvPatchVectorField::readPsi
(
 const dictionary& dict
) const
{
 if (dict.found("psi"))
 {
 return tmp<scalarField>
 (
 new scalarField("psi", dict, patch.size)
)
 }

 const fileName psiFile(boundaryDataDir/"psi")
 if (!isFile(psiFile))
 {
 Info<< "turbulentDFMVeerInlet " << patch.name
 << ": no psi data found, psi = 0 (no veer)" << endl
 return tmp<scalarField>(new scalarField(patch.size, 0.0))
 }

 IFstream is(psiFile)
 const scalarField psiSamples(is)
 // Interpolate the direction (cos, sin) rather than the angle itself
 // which is safe across the +-180 deg discontinuity
 vectorField dirSamples(psiSamples.size, vector::zero)
 forAll(psiSamples, i)
 {
 const scalar a = degToRad(psiSamples[i])
 dirSamples[i] = vector(cos(a), sin(a), 0)
 }

 const vectorField dirFaces(interpolateHeight(dirSamples, word("psi")))
 tmp<scalarField> tpsi(new scalarField(patch.size, 0.0))
 scalarField& psi = tpsi.ref
 forAll(psi, facei)
 {
 const vector& d = dirFaces[facei]
 if (sqr(d.x) + sqr(d.y) < small)
 {
 FatalErrorInFunction
 << "Ill-defined interpolated wind direction at face "
 << facei << " (opposite directions at neighbouring levels)"
 << exit(FatalError)
 }

 psi[facei] = radToDeg(atan2(d.y, d.x))
 }

 return tpsi
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::calcGeometry
{
 const vectorField nf(patch.nf)
 // Inward unit normal (same convention as TInF)
 patchNormal_ = -gAverage(nf)
 if (mag(patchNormal_) < small)
 {
 FatalErrorInFunction
 << "Cannot determine the normal of patch " << patch.name
 << exit(FatalError)
 }

 forAll(patchNormal_, d)
 {
 if (mag(patchNormal_[d]) <= small)
 {
 patchNormal_[d] = 0
 }
 }
 patchNormal_ /= mag(patchNormal_)
 if (gMax(magSqr(nf + patchNormal_)) > 1e-6)
 {
 WarningInFunction
 << "Patch " << patch.name << " is not planar" << endl
 }

 // Vertical axis orthogonal to the patch normal
 const vector v(vertical_ - (vertical_ & patchNormal_)*patchNormal_)
 if (mag(v) < small)
 {
 FatalErrorInFunction
 << "verticalAxis is parallel to the normal of patch "
 << patch.name << exit(FatalError)
 }

 vertical_ = v/mag(v)
 // In-plane horizontal axis (= +y for normal +x and vertical +z)
 tangent_ = vertical_ ^ patchNormal_
 tangent_ /= mag(tangent_)
 patchSize_.setSize(Pstream::nProcs)
 patchSize_ = 0
 patchSize_[Pstream::myProcNo] = patch.size
 Pstream::gatherList(patchSize_)
 Pstream::scatterList(patchSize_)
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseFrames
{
 label nWeak = 0
 forAll(psi_, facei)
 {
 const scalar a = degToRad(psi_[facei])
 const vector ex(cos(a)*patchNormal_ + sin(a)*tangent_)
 const vector ey(vertical_ ^ ex)
 eMean_[facei] = ex
 // tensor(a, b, c) takes rows; transpose -> columns e_x' e_y' e_z'
 Q_[facei] = tensor(ex, ey, vertical_).T
 if ((ex & patchNormal_) < 0.1)
 {
 ++nWeak
 }
 }

 reduce(nWeak, sumOp<label>)
 if (nWeak)
 {
 WarningInFunction
 << nWeak << " faces have |psi| > ~84 deg: the mean flow is "
 << "(almost) tangential to or out of patch " << patch.name
 << endl
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseParameters
{
 label nBadU = 0
 label nBadR = 0
 label nBadL = 0
 label nFallback = 0
 forAll(U_, facei)
 {
 if (U_[facei] <= 0)
 {
 ++nBadU
 }

 // Lund / Cholesky factor of the local Reynolds stress
 const symmTensor& R = R_[facei]
 const scalar trR = max(R.xx + R.yy + R.zz, vSmall)
 const scalar eps = 1e-10*trR
 tensor B(tensor::zero)
 bool bad = false
 const scalar d0 = R.xx
 if (d0 > eps)
 {
 B.xx = sqrt(d0)
 B.yx = R.xy/B.xx
 B.zx = R.xz/B.xx
 }
 else if (d0 < -eps)
 {
 bad = true
 }

 const scalar d1 = R.yy - sqr(B.yx)
 if (d1 > eps)
 {
 B.yy = sqrt(d1)
 B.zy = (R.yz - B.yx*B.zx)/B.yy
 }
 else if (d1 < -eps)
 {
 bad = true
 }

 const scalar d2 = R.zz - sqr(B.zx) - sqr(B.zy)
 if (d2 > eps)
 {
 B.zz = sqrt(d2)
 }
 else if (d2 < -eps)
 {
 bad = true
 }

 if (bad)
 {
 ++nBadR
 }

 Lund_[facei] = B
 // Target scales: column 0 = along wind (time), column 1 = in-plane
 // horizontal t (ellipsoidal projection), column 2 = vertical
 const tensor& L = L_[facei]
 const vector& ex = eMean_[facei]
 const vector ey(vertical_ ^ ex)
 const scalar a = ex & tangent_; // sin(psi)
 const scalar b = ey & tangent_; // cos(psi)

 tensor Le(L)
 bool badL = false
 for (direction i = 0; i < 3; i++)
 {
 const scalar Lx = L.component(3*i)
 const scalar Ly = L.component(3*i + 1)
 const scalar Lz = L.component(3*i + 2)
 if (Lx <= 0 || Ly <= 0 || Lz <= 0)
 {
 badL = true
 }

 if (mag(a) > small && Lx > 0 && Ly > 0)
 {
 Le.component(3*i + 1) =
 1.0/sqrt(sqr(a/Lx) + sqr(b/Ly))
 }
 }

 if (badL)
 {
 ++nBadL
 }

 // Mixing matrix E_ik = B_ik^2/R_ii and L0 = inv(E) & Leff
 const scalar Rd[3] = {R.xx, R.yy, R.zz}
 tensor E(tensor::zero)
 for (direction i = 0; i < 3; i++)
 {
 if (Rd[i] > eps)
 {
 for (direction k = 0; k < 3; k++)
 {
 E.component(3*i + k) = sqr(B.component(3*i + k))/Rd[i]
 }
 }
 else
 {
 E.component(3*i + i) = 1
 }
 }

 tensor L0(Le)
 if (det(E) > 1e-12)
 {
 L0 = inv(E) & Le
 bool negative = false
 for (direction c = 0; c < tensor::nComponents; c++)
 {
 if (L0.component(c) < 0)
 {
 negative = true
 }
 }

 if (negative)
 {
 L0 = Le
 ++nFallback
 }
 }
 else
 {
 ++nFallback
 }

 Leff_[facei] = Le
 L0_[facei] = L0
 }

 reduce(nBadU, sumOp<label>)
 reduce(nBadR, sumOp<label>)
 reduce(nBadL, sumOp<label>)
 reduce(nFallback, sumOp<label>)
 if (nBadU)
 {
 WarningInFunction
 << nBadU << " faces with U <= 0" << endl
 }
 if (nBadR)
 {
 WarningInFunction
 << nBadR << " faces with non positive semi-definite R; "
 << "negative pivots set to zero" << endl
 }
 if (nBadL)
 {
 WarningInFunction
 << nBadL << " faces with non-positive L components" << endl
 }

 Info<< "turbulentDFMVeerInlet " << patch.name << ": "
 << nFallback << " faces use L0 = Leff (no mixing correction)"
 << endl
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseVirtualGrid
{
 const vectorField& Cf = patch.Cf
 const scalarField sY(Cf & tangent_)
 const scalarField sZ(Cf & vertical_)
 originY_ = gMin(sY)
 originZ_ = gMin(sZ)
 const scalar spanY = gMax(sY) - originY_
 const scalar spanZ = gMax(sZ) - originZ_
 delta_ = sqrt(gMin(patch.magSf))/gridFactor_
 My_ = label(ceil(spanY/delta_)) + 1
 Mz_ = label(ceil(spanZ/delta_)) + 1
 const scalarField sYAll(gatherProc(sY))
 const scalarField sZAll(gatherProc(sZ))
 const scalar dlt = delta_
 auto nearest = [dlt](const scalar d, const label M)
 {
 label i = label(floor(d/dlt))
 if (d - i*dlt > 0.5*dlt)
 {
 ++i
 }
 return min(max(i, label(0)), M - 1)
 }
 yindices_.setSize(sYAll.size)
 zindices_.setSize(sZAll.size)
 forAll(sYAll, I)
 {
 yindices_[I] = nearest(sYAll[I] - originY_, My_)
 zindices_[I] = nearest(sZAll[I] - originZ_, Mz_)
 }

 const label nTot = sYAll.size
 indicesPerProc_ = nTot/Pstream::nProcs
 rest_ = nTot - indicesPerProc_*Pstream::nProcs
 Info<< "turbulentDFMVeerInlet " << patch.name << ": " << nTot
 << " faces, virtual grid " << My_ << " x " << Mz_
 << ", delta = " << delta_ << endl
}


