) const
{
 return max(label(1), label(ceil(l/delta_)))
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::localRange
(
 label& start
 label& nLocal
) const
{
 const label me = Pstream::myProcNo
 if (me < rest_)
 {
 start = me*indicesPerProc_ + me
 nLocal = indicesPerProc_ + 1
 }
 else
 {
 start = me*indicesPerProc_ + rest_
 nLocal = indicesPerProc_
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialiseFilterCoeff
{
 const tensorField L0All(gatherProc(L0_))
 ny_.setSize(L0All.size)
 nz_.setSize(L0All.size)
 nyMax_ = labelVector(1, 1, 1)
 nzMax_ = labelVector(1, 1, 1)
 forAll(L0All, I)
 {
 const tensor& L0 = L0All[I]
 // column 1: in-plane horizontal t, column 2: vertical
 ny_[I] = labelVector(nCells(L0.xy), nCells(L0.yy), nCells(L0.zy))
 nz_[I] = labelVector(nCells(L0.xz), nCells(L0.yz), nCells(L0.zz))
 for (direction c = 0; c < 3; c++)
 {
 nyMax_[c] = max(nyMax_[c], ny_[I][c])
 nzMax_[c] = max(nzMax_[c], nz_[I][c])
 }
 }

 label nyMaxAll = 0
 label nzMaxAll = 0
 for (direction c = 0; c < 3; c++)
 {
 rndSize_[c] =
 (My_ + 2*nfK_*nyMax_[c])*(Mz_ + 2*nfK_*nzMax_[c])
 nyMaxAll = max(nyMaxAll, nyMax_[c])
 nzMaxAll = max(nzMaxAll, nzMax_[c])
 }

 label start, nLocal
 localRange(start, nLocal)
 filterCoeff_.setSize(3)
 for (direction c = 0; c < 3; c++)
 {
 filterCoeff_[c].setSize(nLocal)
 for (label subI = 0; subI < nLocal; subI++)
 {
 const label I = start + subI
 get2DFilterCoeff(filterCoeff_[c][subI], ny_[I][c], nz_[I][c])
 }
 }

 Info<< "turbulentDFMVeerInlet " << patch.name
 << ": max filter widths ny = " << nyMax_ << ", nz = " << nzMax_
 << endl
 if (periodicInY_ && My_ < 2*nfK_*nyMaxAll)
 {
 WarningInFunction
 << "Filter half-width exceeds the periodic span in y" << endl
 }
 if (periodicInZ_ && Mz_ < 2*nfK_*nzMaxAll)
 {
 WarningInFunction
 << "Filter half-width exceeds the periodic span in z" << endl
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::get1DFilterCoeff
(
 scalarList& b
 const label n
) const
{
 if (n <= 0)
 {
 b.setSize(1)
 b[0] = 1.0
 return
 }

 const scalar pi = constant::mathematical::pi
 const label N = nfK_*n
 b.setSize(2*N + 1)
 scalar sum = 0
 for (label k = 0; k < 2*N + 1; k++)
 {
 const scalar r = scalar(k - N)
 if (filterType_ == "gaussian")
 {
 b[k] = exp(-pi*sqr(r)/(2.0*sqr(scalar(n))))
 }
 else if (filterType_ == "bessel")
 {
 b[k] = 0.1505857*bessk0(mag(1.0228626*r/n) + 0.0178114)
 }
 else
 {
 b[k] = exp(-mag(2.0*r/n))
 }

 sum += sqr(b[k])
 }

 sum = sqrt(sum)
 forAll(b, k)
 {
 b[k] /= sum
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::get2DFilterCoeff
(
 scalarList& filter
 const label ny
 const label nz
) const
{
 scalarList by
 scalarList bz
 get1DFilterCoeff(by, ny)
 get1DFilterCoeff(bz, nz)
 filter.setSize(by.size*bz.size)
 forAll(by, i)
 {
 forAll(bz, j)
 {
 filter[get1DIndex(i, j, bz.size)] = by[i]*bz[j]
 }
 }
}


Foam::scalarField
Foam::turbulentDFMVeerInletFvPatchVectorField::getRandomField
(
 const label totalSize
)
{
 List<scalarField> rndProc(Pstream::nProcs)
 const label n = totalSize/Pstream::nProcs
 const label rest = totalSize - n*Pstream::nProcs
 scalarField& myRnd = rndProc[Pstream::myProcNo]
 myRnd.setSize(Pstream::myProcNo < rest ? n + 1 : n)
 forAll(myRnd, i)
 {
 myRnd[i] = rndGen_.scalarNormal
 }

 Pstream::gatherList(rndProc)
 Pstream::scatterList(rndProc)
 return ListListOps::combine<scalarField>(rndProc, accessOp<scalarField>)
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::spatialCorr
{
 label start, nLocal
 localRange(start, nLocal)
 List<vectorField> filteredProc(Pstream::nProcs)
 filteredProc[Pstream::myProcNo].setSize(nLocal, vector::zero)
 vectorField& myFiltered = filteredProc[Pstream::myProcNo]
 for (direction c = 0; c < 3; c++)
 {
 scalarField rnd(getRandomField(rndSize_[c]))
 const label Ny = nfK_*nyMax_[c]
 const label Nz = nfK_*nzMax_[c]
 const label yDim = My_ + 2*Ny
 const label zDim = Mz_ + 2*Nz
 // Periodic padding: same copy order as TInF turbulentDFMInlet
 if (periodicInY_)
 {
 for (label i = 0; i < Ny; i++)
 {
 for (label k = 0; k < zDim; k++)
 {
 rnd[get1DIndex(i, k, zDim)] =
 rnd[get1DIndex(My_ + i, k, zDim)]
 rnd[get1DIndex(My_ + 2*Ny - i - 1, k, zDim)] =
 rnd[get1DIndex(2*Ny - i - 1, k, zDim)]
 }
 }
 }

 if (periodicInZ_)
 {
 for (label i = 0; i < yDim; i++)
 {
 for (label k = 0; k < Nz; k++)
 {
 rnd[get1DIndex(i, k, zDim)] =
 rnd[get1DIndex(i, Mz_ + k, zDim)]
 rnd[get1DIndex(i, Mz_ + Nz + k, zDim)] =
 rnd[get1DIndex(i, Nz + k, zDim)]
 }
 }
 }

 // 2D convolution for the faces handled by this processor
 forAll(myFiltered, subI)
 {
 const label I = start + subI
 const label Ky = nfK_*ny_[I][c]
 const label Kz = nfK_*nz_[I][c]
 const label wz = 2*Kz + 1
 const scalarList& coeff = filterCoeff_[c][subI]
 scalar sum = 0
 for (label ii = 0; ii <= 2*Ky; ii++)
 {
 const label row = yindices_[I] + Ny - Ky + ii
 const label rowStart =
 get1DIndex(row, zindices_[I] + Nz - Kz, zDim)
 const label cStart = ii*wz
 for (label jj = 0; jj < wz; jj++)
 {
 sum += rnd[rowStart + jj]*coeff[cStart + jj]
 }
 }

 myFiltered[subI][c] = sum
 }
 }

 Pstream::gatherList(filteredProc)
 Pstream::scatterList(filteredProc)
 const vectorField filteredAll
 (
 ListListOps::combine<vectorField>(filteredProc, accessOp<vectorField>)
)
 label offset = 0
 for (label i = 0; i < Pstream::myProcNo; i++)
 {
 offset += patchSize_[i]
 }

 forAll(uFluctFiltered_, facei)
 {
 uFluctFiltered_[facei] = filteredAll[offset + facei]
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::temporalCorr
{
 const scalar dt = db.time.deltaT.value
 forAll(uFluctTemporal_, facei)
 {
 // Convection speed along the local mean wind direction
 const scalar Uc = constMeanU_ ? Uref_ : U_[facei]
 for (direction c = 0; c < 3; c++)
 {
 // Unscaled along-wind scale L_{c x'} (TInF convention)
 const scalar Lt = L_[facei].component(3*c)
 scalar a = 0
 scalar b = 1
 if (Uc > vSmall && Lt > vSmall)
 {
 const scalar T = Lt/Uc
 a = exp(-dt/T)
 b = sqrt(1.0 - exp(-2.0*dt/T))
 }

 uFluctTemporal_[facei][c] =
 a*uFluctTemporalOld_[facei][c]
 + b*uFluctFiltered_[facei][c]
 }
 }

 uFluctTemporalOld_ = uFluctTemporal_
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::writeSamples
{
 if (outputFaces_.empty)
 {
 return
 }

 if (outputFiles_.empty)
 {
 const fileName dir
 (
 db.time.path/"postProcessing"/"turbulentDFMVeerInlet"
 /patch.name/db.time.timeName
)
 mkDir(dir)
 outputFiles_.setSize(outputFaces_.size)
 forAll(outputFaces_, i)
 {
 const label f = outputFaces_[i]
 std::string fname = "face" + std::string(Foam::name(f))
 if (Pstream::parRun)
 {
 fname +=
 "_proc" + std::string(Foam::name(Pstream::myProcNo))
 }
 fname += ".dat"
 outputFiles_.set(i, new OFstream(dir/word(fname)))
 OFstream& os = outputFiles_[i]
 os.precision(12)
 os << "# face " << f << nl
 << "# Cf " << patch.Cf[f] << nl
 << "# U " << U_[f] << nl
 << "# Uconv " << (constMeanU_ ? Uref_ : U_[f]) << nl
 << "# psi " << psi_[f] << nl
 << "# R " << R_[f] << nl
 << "# L " << L_[f] << nl
 << "# Leff " << Leff_[f] << nl
 << "# L0 " << L0_[f] << nl
 << "# delta " << delta_ << nl
 << "# columns: time ux uy uz" << endl
 }
 }

 const vectorField& Up = *this
 forAll(outputFaces_, i)
 {
 const vector& u = Up[outputFaces_[i]]
 outputFiles_[i]
 << db.time.value << ' '
 << u.x << ' ' << u.y << ' ' << u.z << endl
 }
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::initialise
{
 const label n = patch.size
 eMean_.setSize(n)
 Q_.setSize(n)
 Lund_.setSize(n)
 Leff_.setSize(n)
 L0_.setSize(n)
 uFluctFiltered_.setSize(n, vector::zero)
 uFluctTemporalOld_.setSize(n, vector::zero)
 uFluctTemporal_.setSize(n, vector::zero)
 // Keep only valid local output faces
 DynamicList<label> valid
 forAll(outputFaces_, i)
 {
 if (outputFaces_[i] >= 0 && outputFaces_[i] < n)
 {
 valid.append(outputFaces_[i])
 }
 }
 if (valid.size != outputFaces_.size && !Pstream::parRun)
 {
 WarningInFunction
 << "Some outputFaceIndices are out of range and ignored" << endl
 }
 outputFaces_ = valid
 outputFiles_.clear
 calcGeometry
 initialiseFrames
 initialiseParameters
 initialiseVirtualGrid
 initialiseFilterCoeff
 if (isRestart_ && !isCleanRestart_)
 {
 uFluctTemporalOld_ = uFluctTemporal_
 }
 else
 {
 spatialCorr
 uFluctTemporalOld_ = uFluctFiltered_
 }

 isInitialized_ = true
 Info<< "turbulentDFMVeerInlet " << patch.name
 << ": initialised, psi range [" << gMin(psi_) << ", "
 << gMax(psi_) << "] deg" << endl
}


