void Foam::turbulentDFMVeerInletFvPatchVectorField::updateCoeffs
{
 if (updated)
 {
 return
 }

 if (!isInitialized_)
 {
 initialise
 }

 if (curTimeIndex_ != db.time.timeIndex)
 {
 curTimeIndex_ = db.time.timeIndex
 spatialCorr
 temporalCorr
 // Mean along the local wind + rotated local fluctuation
 vectorField& Up = *this
 forAll(Up, facei)
 {
 Up[facei] =
 U_[facei]*eMean_[facei]
 + (Q_[facei] & (Lund_[facei] & uFluctTemporal_[facei]))
 }

 if (correctFlux_)
 {
 const scalar target =
 gSum(U_*(eMean_ & patchNormal_)*patch.magSf)
 const scalar actual = -gSum(Up & patch.Sf)
 if (target > vSmall && actual > vSmall)
 {
 const scalar fCorr = target/actual
 Up *= fCorr
 Info<< "turbulentDFMVeerInlet " << patch.name
 << ": flux correction coefficient " << fCorr << endl
 }
 else
 {
 WarningInFunction
 << "Flux correction skipped (target " << target
 << ", actual " << actual << ")" << endl
 }
 }

 writeSamples
 isRestart_ = true
 }

 fixedValueFvPatchVectorField::updateCoeffs
}


void Foam::turbulentDFMVeerInletFvPatchVectorField::write(Ostream& os) const
{
 fvPatchVectorField::write(os)
 writeEntryIfDifferent<bool>(os, "periodicInY", false, periodicInY_)
 writeEntryIfDifferent<bool>(os, "periodicInZ", false, periodicInZ_)
 writeEntryIfDifferent<bool>(os, "constMeanU", false, constMeanU_)
 writeEntry(os, "Uref", Uref_)
 writeEntryIfDifferent<scalar>(os, "gridFactor", 1.0, gridFactor_)
 writeEntryIfDifferent<label>(os, "filterFactor", 2, nfK_)
 writeEntryIfDifferent<word>(os, "filterType", "exponential", filterType_)
 writeEntryIfDifferent<bool>(os, "correctFlux", true, correctFlux_)
 writeEntryIfDifferent<label>(os, "seed", -1, seed_)
 writeEntryIfDifferent<bool>(os, "cleanRestart", false, isCleanRestart_)
 writeEntry(os, "verticalAxis", vertical_)
 if (outputFaces_.size)
 {
 writeEntry(os, "outputFaceIndices", outputFaces_)
 }

 writeEntry(os, "uFluctTemporal", uFluctTemporal_)
 writeEntry(os, "U", U_)
 writeEntry(os, "R", R_)
 writeEntry(os, "L", L_)
 writeEntry(os, "psi", psi_)
 writeEntry(os, "value", *this)
}


