template<class Type>
Foam::tmp<Foam::Field<Type>>
Foam::turbulentDFMVeerInletFvPatchVectorField::interpolateProfile
(
 const word& fieldName
 const Type& defaultValue
 const bool optional
) const
{
 const fileName dir(boundaryDataDir)
 const fileName valsFile(dir/fieldName)
 if (!isFile(valsFile))
 {
 if (optional)
 {
 Info<< "turbulentDFMVeerInlet " << patch.name << ": "
 << valsFile << " not found, using uniform "
 << defaultValue << endl
 return tmp<Field<Type>>
 (
 new Field<Type>(patch.size, defaultValue)
)
 }

 FatalErrorInFunction
 << "Cannot find " << valsFile << exit(FatalError)
 }

 IFstream ptsIs(dir/"points")
 if (!ptsIs.good)
 {
 FatalErrorInFunction
 << "Cannot read " << dir/"points" << exit(FatalError)
 }

 const pointField pts(ptsIs)
 IFstream valIs(valsFile)
 const Field<Type> vals(valIs)
 if (vals.size != pts.size || pts.empty)
 {
 FatalErrorInFunction
 << valsFile << " has " << vals.size << " entries but "
 << dir/"points" << " has " << pts.size
 << exit(FatalError)
 }

 // Sort by height and merge points at the same height (average)
 const scalarField zs(pts.component(vector::Z))
 SortableList<scalar> zSorted(zs)
 const labelList& order = zSorted.indices
 const scalar span = max(zSorted.last - zSorted.first, small)
 const scalar tol = 1e-6*span
 DynamicList<scalar> zU
 DynamicList<Type> vU
 label k = 0
 while (k < order.size)
 {
 const scalar z0 = zSorted[k]
 scalar zSum = 0
 Type vSum = pTraits<Type>::zero
 label n = 0
 while (k < order.size && zSorted[k] - z0 <= tol)
 {
 zSum += zSorted[k]
 vSum += vals[order[k]]
 n++
 k++
 }

 zU.append(zSum/scalar(n))
 vU.append(vSum/scalar(n))
 }

 // Linear interpolation in z, constant extrapolation at both ends
 const scalarField zf(patch.Cf.component(vector::Z))
 tmp<Field<Type>> tres(new Field<Type>(zf.size))
 Field<Type>& res = tres.ref
 const label nU = zU.size
 label nOut = 0
 forAll(zf, facei)
 {
 const scalar z = zf[facei]
 if (nU == 1)
 {
 res[facei] = vU[0]
 }
 else if (z <= zU[0])
 {
 res[facei] = vU[0]
 if (z < zU[0] - tol) nOut++
 }
 else if (z >= zU[nU - 1])
 {
 res[facei] = vU[nU - 1]
 if (z > zU[nU - 1] + tol) nOut++
 }
 else
 {
 label lo = 0
 label hi = nU - 1
 while (hi - lo > 1)
 {
 const label mid = (lo + hi)/2
 if (zU[mid] <= z)
 {
 lo = mid
 }
 else
 {
 hi = mid
 }
 }

 const scalar w = (z - zU[lo])/(zU[hi] - zU[lo])
 res[facei] = (1.0 - w)*vU[lo] + w*vU[hi]
 }
 }

 reduce(nOut, sumOp<label>)
 Info<< "turbulentDFMVeerInlet " << patch.name << ": field "
 << fieldName << " interpolated by height from " << nU
 << " distinct levels (" << pts.size << " points)"
 if (nOut)
 {
 Info<< ", " << nOut << " faces outside range (end values used)"
 }

 Info<< endl
 return tres
}


