void Foam::turbulentDFMVeerInletFvPatchVectorField::updateCoeffs
{
 if (updated)
 {
 return
 }

 if (!isInitialized_)
 {
 initialise
 isInitialized_ = true
 }

 if (curTimeIndex_ != db.time.timeIndex)
 {
 curTimeIndex_ = db.time.timeIndex
 spatialCorr
 temporalCorr
 vectorField& Up = *this
 // u = U e_x' + Q B' v
 Up = U_*meanDir_ + (LundGlobal_ & uFluctTemporal_)
 // Flux correction: target = sum U cos(psi) |Sf|
 const scalar target =
 gSum(U_*(meanDir_ & patchNormal_)*patch.magSf)
 const scalar actual = gSum(-(Up & patch.Sf))
 scalar fCorr = 1.0
 if (target > vSmall && actual > vSmall)
 {
 fCorr = target/actual
 Up *= fCorr
 }
 else
 {
 WarningInFunction
 << "Flux correction skipped (target " << target
 << ", actual " << actual << ")" << endl
 }

 Info<< "turbulentDFMVeerInlet " << patch.name
 << ": mass flow correction coefficient: " << fCorr << endl
 isRestart_ = true
 }

 fixedValueFvPatchVectorField::updateCoeffs
}


